@dataclass(frozen=True)
class DSPStrategyCandidate:
    strategy_id: str
    method_family: str
    problem: str
    parameters: Dict[str, Any]
    scores: Dict[str, float]
    total_score: float
    confidence: float
    reason: str
    operator_check: str
    rollback_expectation: Dict[str, Any]
    future_wing_readback_contract: Dict[str, Any]
    blockers: Tuple[str, ...] = ()

    @property
    def status(self) -> str:
        return "blocked" if self.blockers else "candidate"

    def to_dict(self) -> Dict[str, Any]:
        payload = asdict(self)
        payload["blockers"] = list(self.blockers)
        payload["status"] = self.status
        return payload


@dataclass(frozen=True)
class SmartDSPRecommendation:
    id: str
    status: str
    target_id: str
    source_role: str
    source_family: str
    mode: str
    selected_strategy: DSPStrategyCandidate
    alternatives: Tuple[DSPStrategyCandidate, ...]
    confidence: float
    reason: str
    residual_risk: str
    operator_explanation: str
    blockers: Tuple[str, ...] = ()
    evidence: Dict[str, Any] = field(default_factory=dict)
    created_at: str = field(default_factory=utc_now)

    def to_dict(self) -> Dict[str, Any]:
        payload = asdict(self)
        payload["selected_strategy"] = self.selected_strategy.to_dict()
        payload["alternatives"] = [candidate.to_dict() for candidate in self.alternatives]
        payload["blockers"] = list(self.blockers)
        return payload

    def operator_safety_blockers(self) -> Tuple[str, ...]:
        return _ordered_unique(
            (
                "smart_dsp_live_apply_quarantined",
                "unsupported_value_type:smart_dsp_strategy",
                "not_in_supervised_fader_gain_executor",
                "real_wing_proof_required_before_live_apply",
                "operator_review_required_before_dsp_promotion",
                "hardware_readback_and_rollback_not_proven",
                "non_fader_live_expansion_requires_separate_adr",
                *self.blockers,
            )
        )

    def to_operator_proposal(self) -> Dict[str, Any]:
        strategy_search_details = self.evidence.get("strategy_search", {})
        alternative_tradeoffs = strategy_search_details.get("alternative_tradeoffs", [])
        operator_explanation_sections = self.evidence.get("operator_explanation_sections", {})
        selected_wing_osc_summary = _candidate_wing_osc_tradeoff_summary(
            self.selected_strategy
        )
        selected_wing_osc_readback_summary = _candidate_wing_osc_readback_summary(
            self.selected_strategy
        )
        proposed_action = {
            "strategy_id": self.selected_strategy.strategy_id,
            "method_family": self.selected_strategy.method_family,
            "problem": self.selected_strategy.problem,
            "parameters": self.selected_strategy.parameters,
            "strategy_scores": self.selected_strategy.scores,
            "total_score": self.selected_strategy.total_score,
            "selected_wing_osc_summary": dict(selected_wing_osc_summary),
            "selected_wing_osc_readback_summary": dict(
                selected_wing_osc_readback_summary
            ),
            **selected_wing_osc_summary,
            **selected_wing_osc_readback_summary,
            "alternatives_considered": [
                {
                    "strategy_id": candidate.strategy_id,
                    "method_family": candidate.method_family,
                    "total_score": candidate.total_score,
                    "status": candidate.status,
                    "blockers": list(candidate.blockers),
                    "why_not_selected": _why_alternative_lost(
                        selected=self.selected_strategy,
                        alternative=candidate,
                        global_blockers=self.blockers,
                    ),
                    "score_gaps": _score_gap_rows(self.selected_strategy, candidate),
                    **_candidate_wing_osc_tradeoff_summary(candidate),
                }
                for candidate in self.alternatives
            ],
            "selected_rationale": strategy_search_details.get("selected_rationale", {}),
            "alternative_tradeoffs": alternative_tradeoffs,
        }
        safety_blockers = list(self.operator_safety_blockers())
        proposal = {
            "id": self.id,
            "method_id": SMART_DSP_METHOD_ID,
            "source": SMART_DSP_METHOD_ID,
            "title": f"{self.target_id}: smart DSP strategy",
            "target": self.target_id,
            "kind": "smart_dsp_strategy",
            "severity": "medium" if self.blockers else "low",
            "confidence": self.confidence,
            "reason": self.reason,
            "operator_explanation": self.operator_explanation,
            "residual_risk": self.residual_risk,
            "strategy_search_details": strategy_search_details,
            "alternative_tradeoffs": alternative_tradeoffs,
            "operator_explanation_sections": operator_explanation_sections,
            "selected_wing_osc_summary": dict(selected_wing_osc_summary),
            "selected_wing_osc_readback_summary": dict(
                selected_wing_osc_readback_summary
            ),
            "queue_action": "not_queueable_until_promoted",
            "can_import_to_queue": False,
            "can_apply_live": False,
            "queue_import_allowed": False,
            "live_apply_allowed": False,
            "read_only_or_dry_run_only": True,
            "live_authority_granted": False,
            "readiness_closure_allowed": False,
            "live_write": False,
            "queue_mutation": False,
            "mutates_mixer": False,
            "blockers": safety_blockers,
            "safety_blockers": safety_blockers,
            "proposed_action": proposed_action,
            "selected_strategy": self.selected_strategy.to_dict(),
            "alternatives": [candidate.to_dict() for candidate in self.alternatives],
            "evidence": {
                **self.evidence,
                "selected_strategy": self.selected_strategy.to_dict(),
                "alternatives": [candidate.to_dict() for candidate in self.alternatives],
                "strategy_search_details": strategy_search_details,
                "alternative_tradeoffs": alternative_tradeoffs,
                "operator_explanation": self.operator_explanation,
                "operator_explanation_sections": operator_explanation_sections,
                "selected_wing_osc_readback_summary": dict(
                    selected_wing_osc_readback_summary
                ),
                "residual_risk": self.residual_risk,
                "live_write": False,
                "queue_mutation": False,
                "transport_free": True,
                "strategy_search": True,
                "readback_required_before_promotion": True,
                "rollback_required_before_promotion": True,
            },
            "old_value": {
                "source": SMART_DSP_OLD_VALUE_SOURCE,
                "required_before_live_promotion": True,
            },
            "rollback_value": {
                "source": SMART_DSP_OLD_VALUE_SOURCE,
                "required_before_live_promotion": True,
            },
        }
        operator_correction = build_operator_correction_payload(
            proposal=proposal,
            method_id=SMART_DSP_METHOD_ID,
            target=self.target_id,
            proposed_action=proposed_action,
            blockers=safety_blockers,
            value_type="smart_dsp_strategy",
            target_kind="offline_soundcheck_live_strategy_selection",
            old_value_source=SMART_DSP_OLD_VALUE_SOURCE,
        )
        operator_correction = {
            **operator_correction,
            "selected_wing_osc_summary": dict(selected_wing_osc_summary),
            "selected_wing_osc_readback_summary": dict(
                selected_wing_osc_readback_summary
            ),
            **selected_wing_osc_summary,
            **selected_wing_osc_readback_summary,
        }
        proposal["operator_correction"] = operator_correction
        return proposal


def _candidate_score(
    scores: Mapping[str, Any],
    *,
    mode: str,
    blockers: Sequence[str],
) -> float:
    normalized = {
        "speed": _clip01(scores.get("speed")),
        "precision": _clip01(scores.get("precision")),
        "musical": _clip01(scores.get("musical")),
        "safety": _clip01(scores.get("safety")),
        "reversibility": _clip01(scores.get("reversibility")),
        "operator_clarity": _clip01(scores.get("operator_clarity")),
    }
    if mode == "live":
        weights = {
            "speed": 0.14,
            "precision": 0.2,
            "musical": 0.18,
            "safety": 0.32,
            "reversibility": 0.1,
            "operator_clarity": 0.06,
        }
    else:
        weights = {
            "speed": 0.22,
            "precision": 0.26,
            "musical": 0.22,
            "safety": 0.18,
            "reversibility": 0.07,
            "operator_clarity": 0.05,
        }
    score = sum(normalized[key] * weight for key, weight in weights.items())
    score -= min(len(blockers) * 0.18, 0.54)
    return round(_clip(score, 0.0, 1.0), 3)


def _rollback_expectation(method_family: str) -> Dict[str, Any]:
    return {
        "required_before_live_promotion": True,
        "method_family": method_family,
        "restore_previous_values_from_readback": True,
        "operator_rollback_required_if_promoted": True,
        "live_write": False,
    }


def _wing_target_surface_index(target_id: str) -> Tuple[str, Optional[int], bool]:
    target = str(target_id or "").strip().lower().replace("/", ":")
    if target in WING_MAIN_TARGET_ALIASES:
        return "main", 1, True
    if ":" not in target:
        return "unresolved", None, False
    raw_surface, raw_index = target.split(":", 1)
    surface = WING_TARGET_SURFACE_ALIASES.get(raw_surface, raw_surface)
    if surface not in WING_TARGET_INDEX_RANGE_BY_SURFACE:
        return "unresolved", None, False
    if surface == "main" and raw_index in WING_MAIN_INDEX_ALIASES:
        return "main", 1, True
    if not raw_index.isdigit():
        return surface, None, False
    index = int(raw_index)
    index_range = WING_TARGET_INDEX_RANGE_BY_SURFACE.get(surface)
    minimum, maximum = index_range
    return surface, index, minimum <= index <= maximum


def _wing_target_base_template(target_id: str) -> Tuple[Optional[str], str]:
    surface, _index, _valid = _wing_target_surface_index(target_id)
    if surface == "unresolved":
        return None, "unresolved"
    bases = {
        "channel": "/ch/{channel}",
        "aux": "/aux/{aux}",
        "bus": "/bus/{bus}",
        "main": "/main/{main}",
        "matrix": "/mtx/{matrix}",
        "fx": "/fx/{fx}",
    }
    return bases.get(surface), surface


def _wing_target_has_concrete_console_index(target_id: str) -> bool:
    _surface, _index, valid = _wing_target_surface_index(target_id)
    return valid


def _wing_sidechain_source_alias_from_target_id(target_id: str) -> str:
    surface, index, valid = _wing_target_surface_index(target_id)
    surface_map = {
        "channel": ("CH", 40),
        "bus": ("BUS", 16),
        "main": ("MAIN", 4),
        "matrix": ("MTX", 8),
        "aux": ("AUX", 8),
    }
    mapping = surface_map.get(surface)
    if mapping is None or not valid or index is None:
        return ""
    prefix, _maximum = mapping
    alias = f"{prefix}.{index}"
    if alias not in WING_COMPRESSOR_SIDECHAIN_SOURCE_VALUES:
        return ""
    return alias


def _wing_sidechain_source_target_diagnostics(target_id: str) -> Dict[str, Any]:
    target = str(target_id or "").strip().lower().replace("/", ":")
    _base, surface = _wing_target_base_template(target)
    alias = _wing_sidechain_source_alias_from_target_id(target)
    result: Dict[str, Any] = {
        "source_target_id": str(target_id or "").strip(),
        "source_target_surface": surface,
        "candidate_source_alias": alias,
        "concrete_source_available": bool(alias),
        "required_source_alias_format": "CH.n, BUS.n, MAIN.n, MTX.n or AUX.n",
    }
    if alias:
        result["source_target_parse_blocker"] = ""
    elif not target:
        result["source_target_parse_blocker"] = (
            "wing_dynamic_eq_external_key_source_requires_reference_target_id"
        )
    elif surface == "unresolved":
        result["source_target_parse_blocker"] = (
            "wing_dynamic_eq_external_key_source_target_requires_concrete_wing_surface"
        )
    elif surface == "fx":
        result["source_target_parse_blocker"] = (
            "wing_dynamic_eq_external_key_source_target_surface_not_supported_for_sidechain"
        )
    else:
        result["source_target_parse_blocker"] = (
            "wing_dynamic_eq_external_key_source_target_requires_numeric_wing_index"
        )
    return result


def _wing_target_resolves_to_osc_surface(target_id: str, method_family: str) -> bool:
    if method_family in {"analysis", "analysis_only"}:
        return True
    return bool(_wing_target_path_templates(target_id, method_family))


def _effective_wing_target_id(
    target_id: str,
    parameters: Mapping[str, Any],
    *,
    method_family: str,
) -> str:
    override = str(parameters.get("wing_osc_target_id_override") or "").strip()
    if (
        method_family == "gain_fader"
        and override
        and (
            parameters.get("soundcheck_master_output_target_surface") == "main"
            or parameters.get("live_master_true_peak_target_surface") == "main"
        )
    ):
        return override
    if (
        method_family == "gain_fader"
        and override
        and parameters.get("wing_gain_target_override_requires_concrete_surface")
        is True
        and _wing_target_resolves_to_osc_surface(override, "gain_fader")
    ):
        return override
    if method_family == "gain_fader" and parameters.get(
        "wing_gain_target_override_required"
    ) is True:
        return "unresolved:required_wing_gain_target_override"
    return target_id


def _summed_bus_gain_target_override_parameters(
    analysis: SmartDSPAnalysisInput,
    *,
    reason: str,
) -> Dict[str, Any]:
    target_id = str(analysis.summed_bus_target_id or "").strip()
    _base, surface = _wing_target_base_template(target_id)
    parameters: Dict[str, Any] = {
        "summed_bus_target_id": target_id,
        "wing_gain_target_override_required": True,
        "wing_gain_target_override_requires_concrete_surface": True,
        "wing_gain_target_override_required_surface": "bus_main_or_matrix",
        "wing_gain_target_override_source_field": "summed_bus_target_id",
        "wing_gain_target_override_reason": reason,
    }
    if (
        target_id
        and surface in {"bus", "main", "matrix"}
        and _wing_target_resolves_to_osc_surface(target_id, "gain_fader")
    ):
        parameters["wing_osc_target_id_override"] = target_id
        return parameters
    parameters.update(
        {
            "wing_gain_target_override_blocker": (
                "summed_bus_rebalance_requires_concrete_wing_bus_target"
            ),
            "wing_gain_target_override_missing_target_id": not bool(target_id),
            "wing_gain_target_override_unresolved_surface": surface,
        }
    )
    return parameters


def _summed_bus_gain_target_override_blockers(
    parameters: Mapping[str, Any],
) -> Tuple[str, ...]:
    blocker = str(parameters.get("wing_gain_target_override_blocker") or "").strip()
    return (blocker,) if blocker else ()


def _wing_native_eq_parametric_band_count(target_id: str) -> int:
    _base, surface = _wing_target_base_template(target_id)
    return int(WING_NATIVE_EQ_PARAMETRIC_BAND_COUNT_BY_SURFACE.get(surface, 0))


def _wing_native_eq_parametric_band_count_source(target_id: str) -> str:
    _base, surface = _wing_target_base_template(target_id)
    capacity = _wing_native_eq_parametric_band_count(target_id)
    if capacity <= 0:
        return "WING Rack fw3.0.5 has no verified native STD EQ band OSC surface"
    return (
        f"WING Rack fw3.0.5 native {surface} STD EQ parametric bands "
        f"B=1-{capacity}"
    )


def _wing_target_path_templates(target_id: str, method_family: str) -> Tuple[str, ...]:
    base, surface = _wing_target_base_template(target_id)
    if base is None:
        return ()
    if not _wing_target_has_concrete_console_index(target_id):
        return ()

    if method_family == "de_esser":
        if surface != "channel":
            return ()
        return (
            f"{base}/gate/on",
            f"{base}/gate/mdl",
            f"{base}/gate/f",
            f"{base}/gate/range",
            f"{base}/gate/mode",
        )

    if method_family == "dynamic_eq":
        if surface != "channel":
            return ()
        return (
            f"{base}/gate/on",
            f"{base}/gate/mdl",
            f"{base}/gate/thr",
            f"{base}/gate/ratio",
            f"{base}/gate/att",
            f"{base}/gate/rel",
            f"{base}/gate/filt",
            f"{base}/gate/g",
            f"{base}/gate/f",
            f"{base}/gate/q",
            f"{base}/gate/mode",
        )

    if method_family in {"eq", "multiband"}:
        if surface not in WING_EQ_SUPPORTED_SURFACES:
            return ()
        if base.startswith("/ch/"):
            return (
                f"{base}/flt/lc",
                f"{base}/flt/lcf",
                f"{base}/flt/lcs",
                f"{base}/flt/hc",
                f"{base}/flt/hcf",
                f"{base}/flt/hcs",
                f"{base}/eq/on",
                f"{base}/eq/mdl",
                f"{base}/eq/mix",
                f"{base}/eq/lg",
                f"{base}/eq/lf",
                f"{base}/eq/lq",
                f"{base}/eq/leq",
                f"{base}/eq/{{band}}f",
                f"{base}/eq/{{band}}g",
                f"{base}/eq/{{band}}q",
                f"{base}/eq/hg",
                f"{base}/eq/hf",
                f"{base}/eq/hq",
                f"{base}/eq/heq",
            )
        return (
            f"{base}/eq/on",
            f"{base}/eq/mdl",
            f"{base}/eq/mix",
            f"{base}/eq/lg",
            f"{base}/eq/lf",
            f"{base}/eq/lq",
            f"{base}/eq/leq",
            f"{base}/eq/{{band}}f",
            f"{base}/eq/{{band}}g",
            f"{base}/eq/{{band}}q",
            f"{base}/eq/hg",
            f"{base}/eq/hf",
            f"{base}/eq/hq",
            f"{base}/eq/heq",
        )
    if method_family == "dynamics":
        if surface == "aux":
            return (
                f"{base}/dyn/on",
                f"{base}/dyn/thr",
                f"{base}/dyn/depth",
                f"{base}/dyn/fast",
                f"{base}/dyn/peak",
                f"{base}/dyn/ingain",
                f"{base}/dyn/cpeak",
                f"{base}/dyn/cmode",
            )
        threshold_path = _wing_dynamics_threshold_path_template(base, surface)
        if threshold_path is None:
            return ()
        return (
            f"{base}/dyn/on",
            f"{base}/dyn/mdl",
            f"{base}/dyn/mix",
            f"{base}/dyn/gain",
            threshold_path,
            f"{base}/dyn/ratio",
            f"{base}/dyn/knee",
            f"{base}/dyn/det",
            f"{base}/dyn/att",
            f"{base}/dyn/hld",
            f"{base}/dyn/rel",
            f"{base}/dyn/env",
            f"{base}/dyn/auto",
            f"{base}/dynxo/depth",
            f"{base}/dynxo/type",
            f"{base}/dynxo/f",
            f"{base}/dynsc/type",
            f"{base}/dynsc/f",
            f"{base}/dynsc/q",
            f"{base}/dynsc/src",
            f"{base}/dynsc/tap",
        )
    if method_family in {"gate", "expander"}:
        threshold_path = _wing_gate_threshold_path_template(base, surface)
        if threshold_path is None:
            return ()
        return (
            f"{base}/gate/on",
            f"{base}/gate/mdl",
            threshold_path,
            f"{base}/gate/range",
            f"{base}/gate/att",
            f"{base}/gate/hld",
            f"{base}/gate/rel",
            f"{base}/gate/acc",
            f"{base}/gate/ratio",
            f"{base}/gatesc/type",
            f"{base}/gatesc/f",
            f"{base}/gatesc/q",
            f"{base}/gatesc/src",
            f"{base}/gatesc/tap",
        )
    if method_family == "fx":
        return (
            "/ch/{channel}/send/{send}/on",
            "/ch/{channel}/send/{send}/lvl",
            "/aux/{aux}/send/{send}/on",
            "/aux/{aux}/send/{send}/lvl",
            "/bus/{bus}/send/{send}/on",
            "/bus/{bus}/send/{send}/lvl",
            "/fx/{fx}/mdl",
            "/fx/{fx}/fxmix",
            "/fx/{fx}/{model_parameter}",
        )
    if method_family == "pan":
        if surface not in WING_PAN_WIDTH_SUPPORTED_SURFACES:
            return ()
        return (f"{base}/pan", f"{base}/wid")
    if method_family in {"gain_fader", "master_bus"}:
        if surface not in WING_GAIN_TRIM_SUPPORTED_SURFACES:
            return ()
        return (f"{base}/fdr", f"{base}/in/set/trim")
    if method_family == "mute":
        if surface not in WING_MUTE_SUPPORTED_SURFACES:
            return ()
        return (f"{base}/mute",)
    return ()


def _numeric_float_or_none(value: Any) -> Optional[float]:
    try:
        numeric = float(value)
    except (TypeError, ValueError):
        return None
    return numeric if math.isfinite(numeric) else None


def _wing_mute_bool_or_none(value: Any) -> Optional[bool]:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        numeric = float(value)
        if not math.isfinite(numeric):
            return None
        if numeric == 0.0:
            return False
        if numeric == 1.0:
            return True
        return None
    if isinstance(value, str):
        token = value.strip().lower().replace("-", "_").replace(" ", "_")
        if token in {"true", "1", "on", "yes", "muted", "mute", "mute_on"}:
            return True
        if token in {"false", "0", "off", "no", "unmuted", "unmute", "mute_off"}:
            return False
    return None


def _wing_eq_gain_db(parameters: Mapping[str, Any]) -> Optional[float]:
    for key in (
        "gain_db",
        "target_cut_db",
        "counterpart_cut_db",
        "broad_cut_db",
        "bounded_boost_db",
        "static_gain_db",
    ):
        numeric = _numeric_float_or_none(parameters.get(key))
        if numeric is not None:
            return numeric
    return None


def _wing_eq_filter_family(filter_type: Any) -> str:
    normalized = _normalize_token(filter_type, "")
    if normalized in {"", "none", "hold", "no_change", "analysis_only"}:
        return "no_eq_change"
    if normalized in {"peaking", "broad_cut", "wide_presence", "presence"}:
        return "parametric_band"
    if normalized == "notch_stack":
        return "parametric_notch_stack"
    if normalized in {"high_pass", "hpf", "low_cut", "rumble_cut"}:
        return "channel_low_cut"
    if normalized in {"low_pass", "lpf", "high_cut", "top_cut", "air_limit"}:
        return "channel_high_cut"
    if normalized in {"low_shelf", "low_shelving"}:
        return "low_shelf"
    if normalized in {
        "high_shelf",
        "air_shelf",
        "presence_shelf",
        "high_shelf_or_wide_presence",
    }:
        return "high_shelf"
    return "unsupported"


def _wing_eq_unsupported_mapping(
    *,
    target_id: str,
    filter_type: Any,
    reason: str,
) -> Dict[str, Any]:
    _base, surface = _wing_target_base_template(target_id)
    return {
        "wing_eq_mapping_required": True,
        "wing_eq_value_mapping_supported": False,
        "wing_eq_mapping_blocker": WING_EQ_VALUE_MAPPING_BLOCKER,
        "wing_eq_mapping_unsupported_reason": reason,
        "wing_eq_filter_type_original": filter_type,
        "wing_eq_target_surface": surface,
        "wing_eq_required_model": WING_EQ_REQUIRED_MODEL,
        "wing_eq_model_readback_required": True,
        "wing_eq_reference": WING_RACK_OSC_PROTOCOL_REFERENCE,
    }


def _wing_eq_parametric_operation(
    *,
    frequency_hz: float,
    gain_db: float,
    q: float,
    filter_type: str,
    band_number: Optional[int] = None,
) -> Dict[str, Any]:
    operation: Dict[str, Any] = {
        "filter_family": "parametric_band",
        "filter_type": filter_type,
        "frequency_hz": round(
            _clip(
                frequency_hz,
                WING_EQ_PARAMETRIC_FREQ_MIN_HZ,
                WING_EQ_PARAMETRIC_FREQ_MAX_HZ,
            ),
            3,
        ),
        "gain_db": round(_clip(gain_db, WING_EQ_GAIN_MIN_DB, WING_EQ_GAIN_MAX_DB), 3),
        "q": round(_clip(q, WING_EQ_Q_MIN, WING_EQ_Q_MAX), 3),
        "path_suffixes": {
            "frequency": "eq/{band}f",
            "gain": "eq/{band}g",
            "q": "eq/{band}q",
        },
        "value_type": "float",
        "band_readback_required": True,
        "protected_band_policy": (
            "do_not_overwrite_feedback_notch_or_operator_locked_band"
        ),
    }
    if band_number is not None:
        operation["native_band_number"] = band_number
    return operation


def _wing_eq_selected_write_keys_for_family(filter_family: Any) -> Tuple[str, ...]:
    base_keys = ("wing_eq_on_osc_value", "wing_eq_mix_osc_value")
    normalized = str(filter_family or "")
    if normalized == "channel_low_cut":
        return (
            *base_keys,
            "wing_eq_low_cut_enabled_osc_value",
            "wing_eq_low_cut_frequency_hz",
            "wing_eq_low_cut_slope_db_per_octave",
        )
    if normalized == "channel_high_cut":
        return (
            *base_keys,
            "wing_eq_high_cut_enabled_osc_value",
            "wing_eq_high_cut_frequency_hz",
            "wing_eq_high_cut_slope_db_per_octave",
        )
    if normalized == "strip_low_cut":
        return (
            *base_keys,
            "wing_eq_strip_low_cut_frequency_hz",
            "wing_eq_strip_low_cut_q",
            "wing_eq_strip_low_cut_type_osc_value",
        )
    if normalized == "low_shelf":
        return (
            *base_keys,
            "wing_eq_low_shelf_gain_db",
            "wing_eq_low_shelf_frequency_hz",
            "wing_eq_low_shelf_q",
            "wing_eq_low_shelf_type_osc_value",
        )
    if normalized == "high_shelf":
        return (
            *base_keys,
            "wing_eq_high_shelf_gain_db",
            "wing_eq_high_shelf_frequency_hz",
            "wing_eq_high_shelf_q",
            "wing_eq_high_shelf_type_osc_value",
        )
    if normalized in {"parametric_band", "parametric_notch_stack"}:
        return (*base_keys, "wing_eq_band_operations")
    return ()


def _wing_eq_write_key_contract(filter_family: Any) -> Dict[str, Any]:
    selected = _wing_eq_selected_write_keys_for_family(filter_family)
    selected_set = set(selected)
    return {
        "wing_eq_write_key_selection_policy": WING_EQ_WRITE_KEY_SELECTION_POLICY,
        "wing_eq_apply_only_selected_write_keys": True,
        "wing_eq_selected_write_keys": list(selected),
        "wing_eq_forbidden_write_keys": [
            key for key in WING_EQ_WRITE_PARAMETER_KEYS if key not in selected_set
        ],
    }


def _wing_selected_present_write_keys(
    parameters: Mapping[str, Any],
    write_parameter_keys: Sequence[str],
) -> Tuple[str, ...]:
    return tuple(key for key in write_parameter_keys if key in parameters)


def _wing_selected_write_key_contract(
    parameters: Mapping[str, Any],
    *,
    prefix: str,
    write_parameter_keys: Sequence[str],
    selection_policy: str,
) -> Dict[str, Any]:
    selected = _wing_selected_present_write_keys(parameters, write_parameter_keys)
    selected_set = set(selected)
    return {
        f"{prefix}_write_key_selection_policy": selection_policy,
        f"{prefix}_apply_only_selected_write_keys": True,
        f"{prefix}_selected_write_keys": list(selected),
        f"{prefix}_forbidden_write_keys": [
            key for key in write_parameter_keys if key not in selected_set
        ],
    }


def _wing_selected_parameter_path_suffix(
    parameters: Mapping[str, Any],
    key: str,
) -> Optional[str]:
    base = key[: -len("_osc_value")] if key.endswith("_osc_value") else key
    direct_suffix = parameters.get(f"{base}_osc_path_suffix")
    if direct_suffix:
        return str(direct_suffix)

    for mapping_key, mapping in parameters.items():
        if not str(mapping_key).endswith("_osc_path_suffixes"):
            continue
        if not isinstance(mapping, Mapping):
            continue
        for raw_name, raw_suffix in mapping.items():
            name = str(raw_name)
            semantic_suffixes = (
                f"_{name}",
                f"_{name}_enabled",
                f"_{name}_hz",
                f"_{name}_db",
                f"_{name}_q",
                f"_{name}_percent",
                f"_{name}_db_per_octave",
                f"_{name}_osc_value",
            )
            if base.endswith(semantic_suffixes):
                return str(raw_suffix)
    return None


def _wing_selected_parameter_rollback_operations(
    parameters: Mapping[str, Any],
    *,
    selected_write_keys: Sequence[str],
    contract_name: str,
) -> List[Dict[str, Any]]:
    operations: List[Dict[str, Any]] = []
    for raw_key in selected_write_keys:
        key = str(raw_key)
        if key not in parameters:
            continue
        base = key[: -len("_osc_value")] if key.endswith("_osc_value") else key
        path_suffix = _wing_selected_parameter_path_suffix(parameters, key)
        if not path_suffix:
            continue
        value_type = parameters.get(f"{base}_value_type")
        operations.append(
            {
                "parameter_key": key,
                "selected_write_key": key,
                "osc_path_suffix": str(path_suffix),
                "osc_value": parameters.get(key),
                "value_type": value_type,
                "read_before_required": True,
                "read_after_required": True,
                "readback_must_match_osc_value": True,
                "previous_value_readback_required": True,
                "previous_value_path_suffix": str(path_suffix),
                "rollback_required": True,
                "rollback_value_source": "previous_value_readback",
                "rollback_path_suffix": str(path_suffix),
                "rollback_readback_required": True,
                "fw305_selected_parameter_rollback_contract": contract_name,
            }
        )
    return operations


