    updated.setdefault("live_eq_on_review_only_value", updated.get("wing_eq_on_osc_value", 1))
    updated.setdefault(
        "live_eq_mix_review_only_value",
        updated.get("wing_eq_mix_osc_value", WING_EQ_MIX_BASELINE_PERCENT),
    )
    updated.setdefault(
        "live_eq_global_on_mix_review_only_reason",
        "live_eq_must_read_existing_eq_on_and_mix_before_band_parameter_apply",
    )
    for key in forbidden_live_write_keys:
        updated.pop(key, None)
    updated["wing_eq_write_key_selection_policy"] = WING_EQ_WRITE_KEY_SELECTION_POLICY
    updated["wing_eq_apply_only_selected_write_keys"] = True
    updated["wing_eq_selected_write_keys"] = list(selected_write_keys)
    updated["wing_eq_forbidden_write_keys"] = [
        key for key in WING_EQ_WRITE_PARAMETER_KEYS if key not in selected_set
    ]
    return updated


