def _wing_compressor_enabled_bool_or_none(value: Any) -> Optional[bool]:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        numeric = float(value)
        if not math.isfinite(numeric):
            return None
        if numeric == 0.0:
            return False
        if numeric == 1.0:
            return True
        return None
    if isinstance(value, str):
        token = value.strip().lower().replace("-", "_").replace(" ", "_")
        if token in {
            "true",
            "1",
            "on",
            "yes",
            "enabled",
            "enable",
            "compressor_on",
            "dynamics_on",
        }:
            return True
        if token in {
            "false",
            "0",
            "off",
            "no",
            "disabled",
            "disable",
            "compressor_off",
            "dynamics_off",
        }:
            return False
    return None


def _wing_compressor_enabled_mapping(enabled: Any) -> Dict[str, Any]:
    parsed = _wing_compressor_enabled_bool_or_none(enabled)
    if parsed is None:
        return {
            "wing_compressor_on_source": (
                "WING Rack fw3.0.5 dyn/on I range 0..1"
            ),
            "wing_compressor_on_osc_path_suffix": "dyn/on",
            "wing_compressor_on_value_type": "integer_bool",
            "wing_compressor_on_original_value": enabled,
            "wing_compressor_on_min": WING_COMPRESSOR_ON_MIN,
            "wing_compressor_on_max": WING_COMPRESSOR_ON_MAX,
            "wing_compressor_on_mapping_policy": (
                "unsupported_compressor_enabled_value_requires_boolean_or_on_off_alias"
            ),
            "wing_compressor_on_parse_blocker": WING_COMPRESSOR_ON_BLOCKER,
        }
    return {
        "wing_compressor_on_source": (
            "WING Rack fw3.0.5 dyn/on I range 0..1"
        ),
        "wing_compressor_on_osc_path_suffix": "dyn/on",
        "wing_compressor_on_osc_value": (
            WING_COMPRESSOR_ON_MAX if parsed else WING_COMPRESSOR_ON_MIN
        ),
        "wing_compressor_on_value_type": "integer_bool",
        "wing_compressor_on_original_value": enabled,
        "wing_compressor_on_min": WING_COMPRESSOR_ON_MIN,
        "wing_compressor_on_max": WING_COMPRESSOR_ON_MAX,
        "wing_compressor_on_mapping_policy": (
            "enable_compressor_when_strategy_writes_native_wing_dynamics"
            if parsed
            else "explicit_compressor_bypass"
        ),
    }


