def _wing_compressor_knee_mapping(knee_db: Any) -> Dict[str, Any]:
    numeric = _numeric_float_or_none(knee_db)
    if numeric is None:
        return {}
    clipped = _clip(
        numeric,
        float(WING_COMPRESSOR_KNEE_MIN),
        float(WING_COMPRESSOR_KNEE_MAX),
    )
    wing_value = int(math.floor(clipped + 0.5))
    wing_value = int(_clip(wing_value, WING_COMPRESSOR_KNEE_MIN, WING_COMPRESSOR_KNEE_MAX))
    return {
        "wing_compressor_knee_source": (
            "WING Rack fw3.0.5 dyn/knee I range 0..5"
        ),
        "wing_compressor_knee_osc_path_suffix": "dyn/knee",
        "wing_compressor_knee_osc_value": wing_value,
        "wing_compressor_knee_value_type": "integer",
        "wing_compressor_knee_quantized_from": round(numeric, 3),
        "wing_compressor_knee_quantization_error": round(
            abs(float(wing_value) - numeric),
            3,
        ),
        "wing_compressor_knee_min": WING_COMPRESSOR_KNEE_MIN,
        "wing_compressor_knee_max": WING_COMPRESSOR_KNEE_MAX,
    }


def _wing_compressor_threshold_mapping(
    target_id: str,
    threshold_dbfs: Any,
) -> Dict[str, Any]:
    _base, surface = _wing_target_base_template(target_id)
    suffix = WING_DYNAMICS_THRESHOLD_PATH_SUFFIX_BY_SURFACE.get(surface)
    if suffix is None:
        return {
            "wing_compressor_threshold_source": "unresolved_wing_osc_target",
            "wing_compressor_threshold_target_surface": surface,
        }
    mapping = {
        "wing_compressor_threshold_source": (
            "WING Rack fw3.0.5 dyn threshold F range -60..0"
        ),
        "wing_compressor_threshold_target_surface": surface,
        "wing_compressor_threshold_osc_path_suffix": f"dyn/{suffix}",
        "wing_compressor_threshold_value_type": "float",
        "wing_compressor_threshold_min_dbfs": WING_COMPRESSOR_THRESHOLD_MIN_DBFS,
        "wing_compressor_threshold_max_dbfs": WING_COMPRESSOR_THRESHOLD_MAX_DBFS,
    }
    numeric = _numeric_float_or_none(threshold_dbfs)
    if numeric is None:
        return mapping
    osc_value = round(
        _clip(
            numeric,
            WING_COMPRESSOR_THRESHOLD_MIN_DBFS,
            WING_COMPRESSOR_THRESHOLD_MAX_DBFS,
        ),
        3,
    )
    mapping.update(
        {
            "wing_compressor_threshold_osc_value": osc_value,
            "wing_compressor_threshold_quantized_from": round(numeric, 3),
            "wing_compressor_threshold_quantization_error": round(
                abs(osc_value - numeric),
                3,
            ),
        }
    )
    return mapping


def _wing_aux_dynamics_int_bool_mapping(
    value: Any,
    *,
    parameter_name: str,
    source: str,
    path_suffix: str,
    original_key: str,
) -> Dict[str, Any]:
    parsed = _wing_compressor_enabled_bool_or_none(value)
    prefix = f"wing_aux_dynamics_{parameter_name}"
    if parsed is None:
        return {
            f"{prefix}_source": source,
            f"{prefix}_osc_path_suffix": path_suffix,
            f"{prefix}_value_type": "integer_bool",
            f"{prefix}_original_value": value,
            f"{prefix}_min": 0,
            f"{prefix}_max": 1,
            f"{prefix}_parse_blocker": (
                f"wing_aux_dynamics_{original_key}_requires_boolean_or_on_off_alias"
            ),
        }
    return {
        f"{prefix}_source": source,
        f"{prefix}_osc_path_suffix": path_suffix,
        f"{prefix}_osc_value": 1 if parsed else 0,
        f"{prefix}_value_type": "integer_bool",
        f"{prefix}_original_value": value,
        f"{prefix}_min": 0,
        f"{prefix}_max": 1,
    }


def _wing_aux_dynamics_bounded_float_mapping(
    *,
    value: Any,
    parameter_name: str,
    source: str,
    path_suffix: str,
    minimum: float,
    maximum: float,
) -> Dict[str, Any]:
    numeric = _numeric_float_or_none(value)
    if numeric is None:
        return {}
    osc_value = round(_clip(numeric, minimum, maximum), 3)
    prefix = f"wing_aux_dynamics_{parameter_name}"
    return {
        f"{prefix}_source": source,
        f"{prefix}_osc_path_suffix": path_suffix,
        f"{prefix}_osc_value": osc_value,
        f"{prefix}_value_type": "float",
        f"{prefix}_min": minimum,
        f"{prefix}_max": maximum,
        f"{prefix}_quantized_from": round(numeric, 3),
        f"{prefix}_quantization_error": round(abs(osc_value - numeric), 3),
    }


def _wing_aux_dynamics_parameter_mapping(
    parameters: Mapping[str, Any],
    *,
    target_id: str,
) -> Dict[str, Any]:
    _base, surface = _wing_target_base_template(target_id)
    if surface != "aux":
        return {}
    mapped: Dict[str, Any] = {
        "wing_aux_dynamics_source": (
            "WING Rack fw3.0.5 /aux/1/dyn PSE/LA combo: on,thr,depth,fast,peak"
        ),
        "wing_aux_dynamics_target_surface": surface,
        "wing_aux_dynamics_reference": WING_RACK_OSC_PROTOCOL_REFERENCE,
        "wing_aux_dynamics_no_channel_compressor_model_slot": True,
        "wing_aux_dynamics_no_dyn_mdl_path": True,
        "wing_aux_dynamics_no_ratio_attack_release_paths": True,
        "wing_aux_dynamics_meter_readback_paths": ["dyn/cpeak"],
        "wing_aux_dynamics_mode_readback_paths": ["dyn/cmode"],
    }
    concrete_keys = {
        "threshold_dbfs",
        "aux_dynamics_threshold_db",
        "aux_dynamics_depth_db",
        "target_gain_reduction_db",
        "max_gain_reduction_db",
        "compressor_enabled",
        "aux_dynamics_fast",
        "compressor_fast_enabled",
        "detector",
        "aux_dynamics_peak",
    }
    if "compressor_enabled" in parameters or bool(concrete_keys & set(parameters)):
        enabled = parameters.get("compressor_enabled", True)
        mapped.update(
            _wing_aux_dynamics_int_bool_mapping(
                enabled,
                parameter_name="on",
                source="WING Rack fw3.0.5 aux dyn/on I range 0..1",
                path_suffix="dyn/on",
                original_key="on",
            )
        )

    threshold = parameters.get(
        "aux_dynamics_threshold_db",
        parameters.get("threshold_dbfs"),
    )
    mapped.update(
        _wing_aux_dynamics_bounded_float_mapping(
            value=threshold,
            parameter_name="threshold",
            source="WING Rack fw3.0.5 aux dyn/thr F range -36..12 dB",
            path_suffix="dyn/thr",
            minimum=WING_AUX_DYNAMICS_THRESHOLD_MIN_DB,
            maximum=WING_AUX_DYNAMICS_THRESHOLD_MAX_DB,
        )
    )

    depth = parameters.get("aux_dynamics_depth_db")
    depth_source = "explicit_aux_dynamics_depth_db"
    if depth is None:
        depth = parameters.get("target_gain_reduction_db")
        depth_source = "bounded_starting_depth_from_target_gain_reduction_db"
    if depth is None:
        depth = parameters.get("max_gain_reduction_db")
        depth_source = "bounded_starting_depth_from_max_gain_reduction_db"
    depth_mapping = _wing_aux_dynamics_bounded_float_mapping(
        value=depth,
        parameter_name="depth",
        source="WING Rack fw3.0.5 aux dyn/depth F range 0..20 dB",
        path_suffix="dyn/depth",
        minimum=WING_AUX_DYNAMICS_DEPTH_MIN_DB,
        maximum=WING_AUX_DYNAMICS_DEPTH_MAX_DB,
    )
    if depth_mapping:
        depth_mapping["wing_aux_dynamics_depth_parameter_source"] = depth_source
        mapped.update(depth_mapping)

    fast = parameters.get("aux_dynamics_fast", parameters.get("compressor_fast_enabled"))
    if fast is None and _numeric_float_or_none(parameters.get("attack_ms")) is not None:
        fast = _safe_float(parameters.get("attack_ms")) <= 15.0
    if fast is not None:
        mapped.update(
            _wing_aux_dynamics_int_bool_mapping(
                fast,
                parameter_name="fast",
                source="WING Rack fw3.0.5 aux dyn/fast I range 0..1",
                path_suffix="dyn/fast",
                original_key="fast",
            )
        )
        mapped["wing_aux_dynamics_fast_parameter_source"] = (
            "explicit_aux_fast_or_attack_ms_threshold"
        )

    peak = parameters.get("aux_dynamics_peak")
    if peak is None and str(parameters.get("detector") or "").strip():
        peak = str(parameters.get("detector") or "").strip().upper() == "PEAK"
    if peak is not None:
        mapped.update(
            _wing_aux_dynamics_int_bool_mapping(
                peak,
                parameter_name="peak",
                source="WING Rack fw3.0.5 aux dyn/peak I range 0..1",
                path_suffix="dyn/peak",
                original_key="peak",
            )
        )
        mapped["wing_aux_dynamics_peak_parameter_source"] = (
            "explicit_aux_peak_or_detector_alias"
        )

    return mapped


