def _wing_gate_enabled_bool_or_none(value: Any) -> Optional[bool]:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        numeric = float(value)
        if not math.isfinite(numeric):
            return None
        if numeric == 0.0:
            return False
        if numeric == 1.0:
            return True
        return None
    if isinstance(value, str):
        token = value.strip().lower().replace("-", "_").replace(" ", "_")
        if token in {"true", "1", "on", "yes", "enabled", "enable", "gate_on"}:
            return True
        if token in {
            "false",
            "0",
            "off",
            "no",
            "disabled",
            "disable",
            "gate_off",
        }:
            return False
    return None


def _wing_gate_enabled_mapping(enabled: Any) -> Dict[str, Any]:
    parsed = _wing_gate_enabled_bool_or_none(enabled)
    if parsed is None:
        return {
            "wing_gate_on_source": "WING Rack fw3.0.5 gate/on I range 0..1",
            "wing_gate_on_osc_path_suffix": "gate/on",
            "wing_gate_on_value_type": "integer_bool",
            "wing_gate_on_original_value": enabled,
            "wing_gate_on_min": WING_GATE_ON_MIN,
            "wing_gate_on_max": WING_GATE_ON_MAX,
            "wing_gate_on_mapping_policy": (
                "unsupported_gate_enabled_value_requires_boolean_or_on_off_alias"
            ),
            "wing_gate_on_parse_blocker": WING_GATE_ON_BLOCKER,
        }
    return {
        "wing_gate_on_source": "WING Rack fw3.0.5 gate/on I range 0..1",
        "wing_gate_on_osc_path_suffix": "gate/on",
        "wing_gate_on_osc_value": WING_GATE_ON_MAX if parsed else WING_GATE_ON_MIN,
        "wing_gate_on_value_type": "integer_bool",
        "wing_gate_on_original_value": enabled,
        "wing_gate_on_min": WING_GATE_ON_MIN,
        "wing_gate_on_max": WING_GATE_ON_MAX,
        "wing_gate_on_mapping_policy": (
            "enable_gate_when_strategy_writes_native_wing_gate_parameters"
            if parsed
            else "explicit_gate_bypass"
        ),
    }


def _wing_gate_threshold_mapping(target_id: str, threshold_dbfs: Any) -> Dict[str, Any]:
    _base, surface = _wing_target_base_template(target_id)
    suffix = WING_GATE_THRESHOLD_PATH_SUFFIX_BY_SURFACE.get(surface)
    if suffix is None:
        return {
            "wing_gate_threshold_source": "unresolved_or_unsupported_wing_gate_surface",
            "wing_gate_threshold_target_surface": surface,
        }
    numeric = _numeric_float_or_none(threshold_dbfs)
    if numeric is None:
        return {
            "wing_gate_threshold_source": (
                "WING Rack fw3.0.5 channel gate threshold path declared"
            ),
            "wing_gate_threshold_target_surface": surface,
            "wing_gate_threshold_osc_path_suffix": f"gate/{suffix}",
            "wing_gate_threshold_value_type": "float",
            "wing_gate_threshold_min_dbfs": WING_GATE_THRESHOLD_MIN_DBFS,
            "wing_gate_threshold_max_dbfs": WING_GATE_THRESHOLD_MAX_DBFS,
        }
    osc_value = round(
        _clip(
            numeric,
            WING_GATE_THRESHOLD_MIN_DBFS,
            WING_GATE_THRESHOLD_MAX_DBFS,
        ),
        3,
    )
    return {
        "wing_gate_threshold_source": (
            "WING Rack fw3.0.5 channel gate threshold F range -80..0 dB"
        ),
        "wing_gate_threshold_target_surface": surface,
        "wing_gate_threshold_osc_path_suffix": f"gate/{suffix}",
        "wing_gate_threshold_osc_value": osc_value,
        "wing_gate_threshold_value_type": "float",
        "wing_gate_threshold_min_dbfs": WING_GATE_THRESHOLD_MIN_DBFS,
        "wing_gate_threshold_max_dbfs": WING_GATE_THRESHOLD_MAX_DBFS,
        "wing_gate_threshold_quantized_from": round(numeric, 3),
        "wing_gate_threshold_quantization_error": round(abs(osc_value - numeric), 3),
    }


