def _wing_gate_ratio_mapping(ratio: Any) -> Dict[str, Any]:
    original_value = ratio
    ratio_text = str(ratio or "").strip().upper()
    if ratio_text == "GATE":
        wing_value = "GATE"
        policy = "explicit_wing_hard_gate_ratio_preserved"
    elif ratio_text in WING_GATE_RATIO_STRINGS:
        wing_value = ratio_text
        policy = "explicit_wing_gate_ratio_preserved"
    else:
        wing_value = _wing_gate_ratio_from_expander_ratio(ratio)
        policy = "numeric_expander_ratio_quantized_to_wing_gate_ratio_enum"
    return {
        "wing_gate_ratio_source": (
            "WING Rack fw3.0.5 gate/ratio S enum 1:1.5, 1:2, 1:3, 1:4, GATE"
        ),
        "wing_gate_ratio_osc_path_suffix": "gate/ratio",
        "wing_gate_ratio_osc_value": wing_value,
        "wing_gate_ratio_value_type": "string_enum",
        "wing_gate_ratio_original_value": original_value,
        "wing_gate_ratio_mapping_policy": policy,
        "wing_gate_ratio_allowed_values": list(WING_GATE_RATIO_ALLOWED_VALUES),
    }


def _wing_gate_sidechain_type_or_none(value: Any) -> Optional[str]:
    token = str(value or "").strip().upper().replace("-", "").replace("_", "")
    aliases = {
        "OFF": "OFF",
        "NONE": "OFF",
        "LP": "LP12",
        "LPF": "LP12",
        "LP12": "LP12",
        "LOWPASS": "LP12",
        "LOWPASS12": "LP12",
        "HP": "HP12",
        "HPF": "HP12",
        "HP12": "HP12",
        "HIGHPASS": "HP12",
        "HIGHPASS12": "HP12",
        "BP": "BP",
        "BPF": "BP",
        "BANDPASS": "BP",
    }
    return aliases.get(token)


def _wing_gate_sidechain_source_or_none(value: Any) -> Optional[str]:
    token = str(value or "").strip().upper().replace(" ", "").replace("_", ".")
    if token in {"", "SELF"}:
        return "SELF"
    if token.startswith("CH") and token[2:].lstrip(".").isdigit():
        channel = int(token[2:].lstrip("."))
        if 1 <= channel <= 40:
            return f"CH.{channel}"
    return None


def _wing_gate_sidechain_tap_or_none(value: Any) -> Optional[str]:
    token = str(value or "").strip().upper().replace("-", "_").replace(" ", "_")
    aliases = {
        "IN": "IN",
        "INPUT": "IN",
        "FILT": "FILT",
        "FILTER": "FILT",
        "PFL": "PFL",
        "AFL": "AFL",
        "POST": "POST",
        "POST_FADER": "POST",
        "3": "3",
        "4": "4",
        "5": "5",
    }
    return aliases.get(token)


def _wing_gate_sidechain_filter_mapping(
    parameters: Mapping[str, Any],
    *,
    target_id: str,
) -> Dict[str, Any]:
    _base, surface = _wing_target_base_template(target_id)
    result: Dict[str, Any] = {
        "wing_gate_sidechain_source": (
            "WING Rack fw3.0.5 gatesc/type,f,q,src,tap sidechain filter"
        ),
        "wing_gate_sidechain_target_surface": surface,
        "wing_gate_sidechain_reference": WING_RACK_OSC_PROTOCOL_REFERENCE,
        "wing_gate_sidechain_apply_only_when_gate_model_matches": True,
    }
    if surface != "channel":
        result["wing_gate_sidechain_surface_blocker"] = (
            "gate_sidechain_filter_requires_channel_surface"
        )
        return result

    filter_type = _wing_gate_sidechain_type_or_none(
        parameters.get("gate_sidechain_filter_type", "BP")
    )
    if filter_type is None:
        result.update(
            {
                "wing_gate_sidechain_type_osc_path_suffix": "gatesc/type",
                "wing_gate_sidechain_type_value_type": "string_enum",
                "wing_gate_sidechain_type_allowed_values": list(
                    WING_GATE_SIDECHAIN_TYPE_VALUES
                ),
                "wing_gate_sidechain_type_original_value": parameters.get(
                    "gate_sidechain_filter_type"
                ),
                "wing_gate_sidechain_type_parse_blocker": (
                    WING_GATE_SIDECHAIN_TYPE_BLOCKER
                ),
            }
        )
        return result

    frequency = _numeric_float_or_none(parameters.get("gate_sidechain_frequency_hz"))
    q = _numeric_float_or_none(parameters.get("gate_sidechain_q"))
    source = _wing_gate_sidechain_source_or_none(
        parameters.get("gate_sidechain_source", "SELF")
    )
    tap = _wing_gate_sidechain_tap_or_none(parameters.get("gate_sidechain_tap", "IN"))
    result.update(
        {
            "wing_gate_sidechain_type_osc_path_suffix": "gatesc/type",
            "wing_gate_sidechain_type_osc_value": filter_type,
            "wing_gate_sidechain_type_value_type": "string_enum",
            "wing_gate_sidechain_type_allowed_values": list(
                WING_GATE_SIDECHAIN_TYPE_VALUES
            ),
            "wing_gate_sidechain_type_original_value": parameters.get(
                "gate_sidechain_filter_type",
                filter_type,
            ),
            "wing_gate_sidechain_frequency_osc_path_suffix": "gatesc/f",
            "wing_gate_sidechain_frequency_value_type": "float_hz",
            "wing_gate_sidechain_frequency_min_hz": WING_GATE_SIDECHAIN_FREQ_MIN_HZ,
            "wing_gate_sidechain_frequency_max_hz": WING_GATE_SIDECHAIN_FREQ_MAX_HZ,
            "wing_gate_sidechain_q_osc_path_suffix": "gatesc/q",
            "wing_gate_sidechain_q_value_type": "float",
            "wing_gate_sidechain_q_min": WING_GATE_SIDECHAIN_Q_MIN,
            "wing_gate_sidechain_q_max": WING_GATE_SIDECHAIN_Q_MAX,
            "wing_gate_sidechain_src_osc_path_suffix": "gatesc/src",
            "wing_gate_sidechain_src_value_type": "string_enum",
            "wing_gate_sidechain_src_allowed_values": list(
                WING_GATE_SIDECHAIN_SOURCE_VALUES
            ),
            "wing_gate_sidechain_tap_osc_path_suffix": "gatesc/tap",
            "wing_gate_sidechain_tap_value_type": "string_enum",
            "wing_gate_sidechain_tap_allowed_values": list(
                WING_GATE_SIDECHAIN_TAP_VALUES
            ),
        }
    )
    if frequency is not None:
        osc_value = round(
            _clip(
                frequency,
                WING_GATE_SIDECHAIN_FREQ_MIN_HZ,
                WING_GATE_SIDECHAIN_FREQ_MAX_HZ,
            ),
            3,
        )
        result.update(
            {
                "wing_gate_sidechain_frequency_osc_value": osc_value,
                "wing_gate_sidechain_frequency_quantized_from": round(frequency, 3),
                "wing_gate_sidechain_frequency_quantization_error": round(
                    abs(osc_value - frequency),
                    3,
                ),
            }
        )
    if q is not None:
        osc_value = round(
            _clip(q, WING_GATE_SIDECHAIN_Q_MIN, WING_GATE_SIDECHAIN_Q_MAX),
            3,
        )
        result.update(
            {
                "wing_gate_sidechain_q_osc_value": osc_value,
                "wing_gate_sidechain_q_quantized_from": round(q, 3),
                "wing_gate_sidechain_q_quantization_error": round(abs(osc_value - q), 3),
            }
        )
    if source is None:
        result["wing_gate_sidechain_src_parse_blocker"] = (
            WING_GATE_SIDECHAIN_SOURCE_BLOCKER
        )
        result["wing_gate_sidechain_src_original_value"] = parameters.get(
            "gate_sidechain_source"
        )
    else:
        result["wing_gate_sidechain_src_osc_value"] = source
        result["wing_gate_sidechain_src_original_value"] = parameters.get(
            "gate_sidechain_source",
            source,
        )
    if tap is None:
        result["wing_gate_sidechain_tap_parse_blocker"] = (
            WING_GATE_SIDECHAIN_TAP_BLOCKER
        )
        result["wing_gate_sidechain_tap_original_value"] = parameters.get(
            "gate_sidechain_tap"
        )
    else:
        result["wing_gate_sidechain_tap_osc_value"] = tap
        result["wing_gate_sidechain_tap_original_value"] = parameters.get(
            "gate_sidechain_tap",
            tap,
        )
    return result


