def _normalize_wing_eq_model(value: Any) -> str:
    token = str(value or "").strip().upper().replace("-", "_").replace(" ", "_")
    if token in {"", "NONE", "OFF", "BYPASS", "DISABLED", "UNKNOWN"}:
        return ""
    aliases = {
        "STD": WING_EQ_REQUIRED_MODEL,
        "STANDARD": WING_EQ_REQUIRED_MODEL,
        "STANDARD_EQ": WING_EQ_REQUIRED_MODEL,
        "STANDARD_EQUALIZER": WING_EQ_REQUIRED_MODEL,
    }
    return aliases.get(token, token)


def _wing_eq_enabled_bool_or_none(value: Any) -> Optional[bool]:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        numeric = float(value)
        if not math.isfinite(numeric):
            return None
        if numeric == 0.0:
            return False
        if numeric == 1.0:
            return True
        return None
    if isinstance(value, str):
        token = value.strip().lower().replace("-", "_").replace(" ", "_")
        if token in {"true", "1", "on", "yes", "enabled", "enable", "eq_on"}:
            return True
        if token in {"false", "0", "off", "no", "disabled", "disable", "eq_off"}:
            return False
    return None


def _wing_eq_model_conflict_state(
    analysis: SmartDSPAnalysisInput,
    *,
    method_family: str,
    parameters: Mapping[str, Any],
) -> Tuple[Dict[str, Any], Tuple[str, ...]]:
    if method_family != "eq" and not parameters.get("wing_eq_mapping_required"):
        return {}, ()
    if parameters.get("wing_eq_value_mapping_supported") is not True:
        return {}, ()
    required_model = _normalize_wing_eq_model(
        parameters.get("wing_eq_required_model", WING_EQ_REQUIRED_MODEL)
    )
    if not required_model:
        return {}, ()

    current_model = _normalize_wing_eq_model(analysis.current_wing_eq_model)
    current_enabled = _wing_eq_enabled_bool_or_none(analysis.current_wing_eq_enabled)
    readback_available = bool(
        analysis.current_wing_eq_model_readback_available or current_model
    )
    operator_owned = bool(analysis.current_wing_eq_operator_owned)
    conflicting_model = bool(
        readback_available and current_model and current_model != required_model
    )
    active_unknown_model = bool(
        not current_model and (current_enabled is True or operator_owned)
    )
    operator_owned_model_edit = bool(
        operator_owned and current_model and current_model == required_model
    )
    blockers: List[str] = []
    if conflicting_model:
        blockers.append(WING_EQ_MODEL_CONFLICT_BLOCKER)
    if active_unknown_model:
        blockers.append(WING_EQ_MODEL_READBACK_BLOCKER)
    if operator_owned_model_edit:
        blockers.append(WING_EQ_OPERATOR_OWNED_MODEL_BLOCKER)

    return (
        {
            "wing_eq_required_model": required_model,
            "wing_eq_required_model_source": "candidate_std_eq_mapping",
            "wing_eq_current_model": current_model,
            "wing_eq_current_enabled": current_enabled,
            "wing_eq_current_operator_owned": operator_owned,
            "wing_eq_model_readback_available": readback_available,
            "wing_eq_model_conflict": conflicting_model,
            "wing_eq_model_readback_required_for_active_slot": active_unknown_model,
            "wing_eq_operator_owned_model_edit_requires_review": (
                operator_owned_model_edit
            ),
            "wing_eq_model_conflict_policy": WING_EQ_MODEL_CONFLICT_POLICY,
            "wing_eq_model_conflict_blocker": (
                WING_EQ_MODEL_CONFLICT_BLOCKER if conflicting_model else None
            ),
            "wing_eq_model_readback_blocker": (
                WING_EQ_MODEL_READBACK_BLOCKER if active_unknown_model else None
            ),
            "wing_eq_operator_owned_model_blocker": (
                WING_EQ_OPERATOR_OWNED_MODEL_BLOCKER
                if operator_owned_model_edit
                else None
            ),
            "wing_eq_model_change_requires_operator_review": (
                conflicting_model or active_unknown_model or operator_owned_model_edit
            ),
            "wing_eq_model_read_before_path": "eq/mdl",
            "wing_eq_on_read_before_path": "eq/on",
            "wing_eq_model_apply_only_when_current_model_matches": True,
        },
        tuple(blockers),
    )


def _wing_eq_filter_operator_owned_state(
    analysis: SmartDSPAnalysisInput,
    *,
    method_family: str,
    parameters: Mapping[str, Any],
) -> Tuple[Dict[str, Any], Tuple[str, ...]]:
    if method_family != "eq":
        return {}, ()
    if parameters.get("wing_eq_value_mapping_supported") is not True:
        return {}, ()
    filter_family = str(parameters.get("wing_eq_filter_family") or "")
    if filter_family not in {"channel_low_cut", "channel_high_cut", "strip_low_cut"}:
        return {}, ()

    operator_owned = bool(analysis.current_wing_eq_filter_operator_owned)
    return (
        {
            "wing_eq_filter_family_operator_owned_scope": filter_family,
            "wing_eq_filter_current_operator_owned": operator_owned,
            "wing_eq_filter_operator_owned_edit_requires_review": operator_owned,
            "wing_eq_filter_operator_owned_blocker": (
                WING_EQ_FILTER_OPERATOR_OWNED_BLOCKER if operator_owned else None
            ),
            "wing_eq_filter_operator_owned_policy": (
                "do_not_overwrite_operator_owned_wing_channel_or_strip_filter_"
                "without_review"
            ),
        },
        (WING_EQ_FILTER_OPERATOR_OWNED_BLOCKER,) if operator_owned else (),
    )


def _normalize_wing_dynamics_model(value: Any) -> str:
    token = str(value or "").strip().upper().replace("-", "_").replace(" ", "_")
    if token in {"", "NONE", "OFF", "BYPASS", "DISABLED", "UNKNOWN"}:
        return ""
    aliases = {
        "COMP": WING_DYNAMICS_REQUIRED_MODEL,
        "COMPRESSOR": WING_DYNAMICS_REQUIRED_MODEL,
        "STANDARD_COMP": WING_DYNAMICS_REQUIRED_MODEL,
        "STANDARD_COMPRESSOR": WING_DYNAMICS_REQUIRED_MODEL,
        "CHANNEL_COMP": WING_DYNAMICS_REQUIRED_MODEL,
        "CHANNEL_COMPRESSOR": WING_DYNAMICS_REQUIRED_MODEL,
    }
    return aliases.get(token, token)


def _wing_dynamics_model_conflict_state(
    analysis: SmartDSPAnalysisInput,
    *,
    method_family: str,
    parameters: Mapping[str, Any],
) -> Tuple[Dict[str, Any], Tuple[str, ...]]:
    if parameters.get("wing_aux_dynamics_no_channel_compressor_model_slot") is True:
        return {}, ()
    dynamics_model_context = (
        method_family in {"dynamics", "multiband"}
        or parameters.get("wing_compressor_model_osc_path_suffix") == "dyn/mdl"
        or parameters.get("wing_compressor_model_readback_required") is True
    )
    if not dynamics_model_context:
        return {}, ()

    required_model = _normalize_wing_dynamics_model(
        parameters.get("wing_compressor_required_model", WING_DYNAMICS_REQUIRED_MODEL)
    )
    if not required_model:
        return {}, ()

    current_model = _normalize_wing_dynamics_model(
        analysis.current_wing_dynamics_model
    )
    current_enabled = _wing_compressor_enabled_bool_or_none(
        analysis.current_wing_dynamics_enabled
    )
    readback_available = bool(
        analysis.current_wing_dynamics_model_readback_available or current_model
    )
    operator_owned = bool(analysis.current_wing_dynamics_operator_owned)
    conflicting_model = bool(
        readback_available and current_model and current_model != required_model
    )
    active_unknown_model = bool(
        not current_model and (current_enabled is True or operator_owned)
    )
    operator_owned_model_edit = bool(
        operator_owned and current_model and current_model == required_model
    )
    blockers: List[str] = []
    if conflicting_model:
        blockers.append(WING_DYNAMICS_MODEL_CONFLICT_BLOCKER)
    if active_unknown_model:
        blockers.append(WING_DYNAMICS_MODEL_READBACK_BLOCKER)
    if operator_owned_model_edit:
        blockers.append(WING_DYNAMICS_OPERATOR_OWNED_MODEL_BLOCKER)

    return (
        {
            "wing_dynamics_required_model": required_model,
            "wing_dynamics_required_model_source": "candidate_comp_mapping",
            "wing_dynamics_current_model": current_model,
            "wing_dynamics_current_enabled": current_enabled,
            "wing_dynamics_current_operator_owned": operator_owned,
            "wing_dynamics_model_readback_available": readback_available,
            "wing_dynamics_model_conflict": conflicting_model,
            "wing_dynamics_model_readback_required_for_active_slot": (
                active_unknown_model
            ),
            "wing_dynamics_operator_owned_model_edit_requires_review": (
                operator_owned_model_edit
            ),
            "wing_dynamics_model_conflict_policy": WING_DYNAMICS_MODEL_CONFLICT_POLICY,
            "wing_dynamics_model_conflict_blocker": (
                WING_DYNAMICS_MODEL_CONFLICT_BLOCKER if conflicting_model else None
            ),
            "wing_dynamics_model_readback_blocker": (
                WING_DYNAMICS_MODEL_READBACK_BLOCKER
                if active_unknown_model
                else None
            ),
            "wing_dynamics_operator_owned_model_blocker": (
                WING_DYNAMICS_OPERATOR_OWNED_MODEL_BLOCKER
                if operator_owned_model_edit
                else None
            ),
            "wing_dynamics_model_change_requires_operator_review": (
                conflicting_model or active_unknown_model or operator_owned_model_edit
            ),
            "wing_dynamics_model_read_before_path": "dyn/mdl",
            "wing_dynamics_on_read_before_path": "dyn/on",
            "wing_dynamics_model_apply_only_when_current_model_matches": True,
        },
        tuple(blockers),
    )


def _normalize_wing_gate_slot_model(value: Any) -> str:
    token = str(value or "").strip().upper().replace("-", "_").replace(" ", "_")
    if token in {"", "NONE", "OFF", "BYPASS", "DISABLED", "UNKNOWN"}:
        return ""
    aliases = {
        "GATE": WING_GATE_REQUIRED_MODEL,
        "EXP": WING_GATE_REQUIRED_MODEL,
        "EXPANDER": WING_GATE_REQUIRED_MODEL,
        "GATE_EXPANDER": WING_GATE_REQUIRED_MODEL,
        "DS902": WING_DE_ESSER_GATE_MODEL,
        "DBX902": WING_DE_ESSER_GATE_MODEL,
        "DBX_902": WING_DE_ESSER_GATE_MODEL,
        "DEESSER": WING_DE_ESSER_GATE_MODEL,
        "DE_ESSER": WING_DE_ESSER_GATE_MODEL,
        "DEQ": WING_DYNAMIC_EQ_GATE_MODEL,
        "DYNAMIC_EQ": WING_DYNAMIC_EQ_GATE_MODEL,
        "DYNAMIC_EQUALIZER": WING_DYNAMIC_EQ_GATE_MODEL,
    }
    return aliases.get(token, token)


def _wing_gate_slot_required_model(
    method_family: str,
    parameters: Mapping[str, Any],
) -> str:
    if method_family == "de_esser" or parameters.get("wing_de_esser_gate_slot_required"):
        return _normalize_wing_gate_slot_model(
            parameters.get("wing_de_esser_required_model", WING_DE_ESSER_GATE_MODEL)
        )
    if method_family == "dynamic_eq" or parameters.get(
        "wing_dynamic_eq_gate_slot_required"
    ):
        return _normalize_wing_gate_slot_model(
            parameters.get("wing_dynamic_eq_required_model", WING_DYNAMIC_EQ_GATE_MODEL)
        )
    if method_family in {"gate", "expander"} or parameters.get(
        "wing_gate_model_osc_path_suffix"
    ) == "gate/mdl":
        return _normalize_wing_gate_slot_model(
            parameters.get("wing_gate_required_model", WING_GATE_REQUIRED_MODEL)
        )
    return ""


def _wing_gate_slot_conflict_policy(
    method_family: str,
    parameters: Mapping[str, Any],
) -> str:
    if method_family == "de_esser" or parameters.get("wing_de_esser_gate_slot_required"):
        return WING_DE_ESSER_GATE_SLOT_CONFLICT_POLICY
    if method_family == "dynamic_eq" or parameters.get(
        "wing_dynamic_eq_gate_slot_required"
    ):
        return WING_DYNAMIC_EQ_GATE_SLOT_CONFLICT_POLICY
    return "requires_gate_slot_readback_and_operator_review_if_other_gate_slot_model_already_active"


def _wing_gate_slot_conflict_state(
    analysis: SmartDSPAnalysisInput,
    *,
    method_family: str,
    parameters: Mapping[str, Any],
) -> Tuple[Dict[str, Any], Tuple[str, ...]]:
    required_model = _wing_gate_slot_required_model(method_family, parameters)
    if not required_model:
        return {}, ()

    current_model = _normalize_wing_gate_slot_model(analysis.current_wing_gate_model)
    current_enabled = _wing_gate_enabled_bool_or_none(
        analysis.current_wing_gate_enabled
    )
    readback_available = bool(
        analysis.current_wing_gate_slot_readback_available or current_model
    )
    operator_owned = bool(analysis.current_wing_gate_slot_operator_owned)
    conflicting_model = bool(current_model and current_model != required_model)
    conflicting_slot_in_use = conflicting_model and (
        current_enabled is not False or operator_owned
    )
    active_unknown_model = bool(
        not current_model and (current_enabled is True or operator_owned)
    )
    operator_owned_model_edit = bool(
        operator_owned and current_model and current_model == required_model
    )
    blockers: List[str] = []
    if conflicting_slot_in_use:
        blockers.append(WING_GATE_SLOT_MODEL_CONFLICT_BLOCKER)
    if active_unknown_model:
        blockers.append(WING_GATE_SLOT_MODEL_READBACK_BLOCKER)
    if operator_owned_model_edit:
        blockers.append(WING_GATE_SLOT_OPERATOR_OWNED_MODEL_BLOCKER)

    return (
        {
            "wing_gate_slot_required_model": required_model,
            "wing_gate_slot_required_model_source": "candidate_method_family",
            "wing_gate_slot_current_model": current_model,
            "wing_gate_slot_current_enabled": current_enabled,
            "wing_gate_slot_current_operator_owned": operator_owned,
            "wing_gate_slot_model_readback_available": readback_available,
            "wing_gate_slot_model_conflict": conflicting_slot_in_use,
            "wing_gate_slot_model_readback_required_for_active_slot": (
                active_unknown_model
            ),
            "wing_gate_slot_operator_owned_model_edit_requires_review": (
                operator_owned_model_edit
            ),
            "wing_gate_slot_model_conflict_policy": _wing_gate_slot_conflict_policy(
                method_family,
                parameters,
            ),
            "wing_gate_slot_model_conflict_blocker": (
                WING_GATE_SLOT_MODEL_CONFLICT_BLOCKER
                if conflicting_slot_in_use
                else None
            ),
            "wing_gate_slot_model_readback_blocker": (
                WING_GATE_SLOT_MODEL_READBACK_BLOCKER
                if active_unknown_model
                else None
            ),
            "wing_gate_slot_operator_owned_model_blocker": (
                WING_GATE_SLOT_OPERATOR_OWNED_MODEL_BLOCKER
                if operator_owned_model_edit
                else None
            ),
            "wing_gate_slot_model_change_requires_operator_review": (
                conflicting_slot_in_use
                or active_unknown_model
                or operator_owned_model_edit
            ),
            "wing_gate_slot_model_read_before_path": "gate/mdl",
            "wing_gate_slot_on_read_before_path": "gate/on",
            "wing_gate_slot_shared_by_models": list(
                WING_GATE_SLOT_SHARED_PROCESSOR_MODELS
            ),
            **_wing_gate_slot_model_precondition_defaults(required_model),
        },
        tuple(blockers),
    )


def _wing_gate_slot_model_precondition_defaults(
    required_model: str,
) -> Dict[str, Any]:
    if not required_model:
        return {}
    return {
        "wing_gate_slot_model_precondition_required": True,
        "wing_gate_slot_model_precondition_required_model": required_model,
        "wing_gate_slot_model_precondition_read_before_paths": [
            "gate/mdl",
            "gate/on",
        ],
        "wing_gate_slot_model_precondition_parameter_apply_requires_model_match": (
            True
        ),
        "wing_gate_slot_model_precondition_model_write_requires_operator_review": (
            True
        ),
        "wing_gate_slot_model_precondition_live_apply_blocked_without_wing_proof": (
            True
        ),
        "wing_gate_slot_model_precondition_no_hidden_model_change": True,
        "wing_gate_slot_model_precondition_shared_processor_surface": "gate",
        "wing_gate_slot_model_precondition_shared_by_models": list(
            WING_GATE_SLOT_SHARED_PROCESSOR_MODELS
        ),
        "wing_gate_slot_model_precondition_path_source": (
            "WING Rack fw3.0.5 gate/mdl and gate/on readback"
        ),
        "wing_gate_slot_model_precondition_operator_check": (
            "Read WING Rack fw3.0.5 gate/mdl and gate/on before applying "
            f"{required_model} gate-slot processor values; do not replace "
            "an operator-owned gate, expander, DS902 de-esser or DEQ dynamic "
            "EQ model without operator review."
        ),
    }


def _wing_gate_slot_model_precondition_readback_fields(
    parameters: Mapping[str, Any],
    *,
    method_family: str,
) -> Dict[str, Any]:
    fields = {
        field: parameters.get(field)
        for field in WING_GATE_SLOT_MODEL_PRECONDITION_FIELDS
        if field in parameters
    }
    if fields:
        return fields
    return _wing_gate_slot_model_precondition_defaults(
        _wing_gate_slot_required_model(method_family, parameters)
    )


