def _make_candidate(
    *,
    strategy_id: str,
    method_family: str,
    problem: str,
    parameters: Dict[str, Any],
    scores: Dict[str, float],
    reason: str,
    operator_check: str,
    analysis: SmartDSPAnalysisInput,
    blockers: Iterable[str] = (),
) -> DSPStrategyCandidate:
    mode = normalize_mode(analysis.mode)
    parameters = _with_wing_native_parameter_mappings(
        parameters,
        target_id=analysis.target_id,
        method_family=method_family,
    )
    all_blockers = list(blockers)
    eq_model_state, eq_model_blockers = _wing_eq_model_conflict_state(
        analysis,
        method_family=method_family,
        parameters=parameters,
    )
    if eq_model_state:
        parameters = {**parameters, **eq_model_state}
    all_blockers.extend(eq_model_blockers)
    eq_filter_state, eq_filter_blockers = _wing_eq_filter_operator_owned_state(
        analysis,
        method_family=method_family,
        parameters=parameters,
    )
    if eq_filter_state:
        parameters = {**parameters, **eq_filter_state}
    all_blockers.extend(eq_filter_blockers)
    dynamics_model_state, dynamics_model_blockers = _wing_dynamics_model_conflict_state(
        analysis,
        method_family=method_family,
        parameters=parameters,
    )
    if dynamics_model_state:
        parameters = {**parameters, **dynamics_model_state}
    all_blockers.extend(dynamics_model_blockers)
    aux_dynamics_state, aux_dynamics_blockers = _wing_aux_dynamics_operator_owned_state(
        analysis,
        method_family=method_family,
        parameters=parameters,
    )
    if aux_dynamics_state:
        parameters = {**parameters, **aux_dynamics_state}
    all_blockers.extend(aux_dynamics_blockers)
    gate_slot_state, gate_slot_blockers = _wing_gate_slot_conflict_state(
        analysis,
        method_family=method_family,
        parameters=parameters,
    )
    if gate_slot_state:
        parameters = {**parameters, **gate_slot_state}
    all_blockers.extend(gate_slot_blockers)
    pan_width_state, pan_width_blockers = _wing_pan_width_operator_owned_state(
        analysis,
        method_family=method_family,
        parameters=parameters,
    )
    if pan_width_state:
        parameters = {**parameters, **pan_width_state}
    all_blockers.extend(pan_width_blockers)
    mute_state, mute_blockers = _wing_mute_operator_owned_state(
        analysis,
        method_family=method_family,
        parameters=parameters,
    )
    if mute_state:
        parameters = {**parameters, **mute_state}
    all_blockers.extend(mute_blockers)
    gain_state, gain_blockers = _wing_gain_operator_owned_state(
        analysis,
        method_family=method_family,
        parameters=parameters,
    )
    if gain_state:
        parameters = {**parameters, **gain_state}
    all_blockers.extend(gain_blockers)
    fx_level_state, fx_level_blockers = _wing_fx_level_operator_owned_state(
        analysis,
        method_family=method_family,
        parameters=parameters,
    )
    if fx_level_state:
        parameters = {**parameters, **fx_level_state}
    all_blockers.extend(fx_level_blockers)
    gain_db = _safe_float(parameters.get("gain_db"), 0.0)
    delta_db = _safe_float(parameters.get("delta_db"), 0.0)
    bounded_delta_db = _safe_float(parameters.get("bounded_delta_db"), 0.0)
    makeup_gain_db = _safe_float(parameters.get("makeup_gain_db"), 0.0)
    send_delta_db = _safe_float(parameters.get("send_delta_db"), 0.0)
    return_delta_db = _safe_float(parameters.get("return_delta_db"), 0.0)
    target_pan = parameters.get("target_pan_percent")
    target_width = parameters.get("target_width_percent")
    width_delta = _safe_float(parameters.get("width_delta_percent"), 0.0)
    aggressive = bool(parameters.get("aggressive"))
    gain_up_db = max(gain_db, delta_db, bounded_delta_db if delta_db > 0.0 else 0.0, 0.0)
    width_widening = width_delta > 0.0 or _safe_float(target_width, 0.0) > 100.0

    if gain_db > 0.0 and analysis.true_peak_headroom_db < gain_db + MIN_TRUE_PEAK_HEADROOM_DB:
        all_blockers.append("insufficient_true_peak_headroom_for_boost")
    if (
        gain_up_db > 0.0
        and analysis.summed_bus_evidence_available
        and analysis.summed_bus_true_peak_headroom_db < gain_up_db + MIN_TRUE_PEAK_HEADROOM_DB
    ):
        all_blockers.append("summed_bus_headroom_blocks_gain_up")
    if (
        gain_up_db > 0.0
        and analysis.summed_bus_evidence_available
        and analysis.summed_bus_level_plane_error_lu >= SUMMED_BUS_REBALANCE_ERROR_LU
    ):
        all_blockers.append("summed_bus_level_plane_rebalance_required")
    if gain_db > 0.0 and analysis.feedback_risk >= HIGH_FEEDBACK_RISK:
        all_blockers.append("feedback_risk_blocks_boost")
    if makeup_gain_db > 0.0 and analysis.true_peak_headroom_db < (
        makeup_gain_db + MIN_TRUE_PEAK_HEADROOM_DB
    ):
        all_blockers.append("makeup_gain_headroom_low")
    if (
        makeup_gain_db > 0.0
        and analysis.summed_bus_evidence_available
        and analysis.summed_bus_true_peak_headroom_db
        < makeup_gain_db + MIN_TRUE_PEAK_HEADROOM_DB
    ):
        all_blockers.append("summed_bus_headroom_blocks_compressor_makeup")
    if (send_delta_db > 0.0 or return_delta_db > 0.0) and (
        analysis.monitor_feedback_risk >= HIGH_MONITOR_FEEDBACK_RISK
        or analysis.fx_return_headroom_db < 1.5
    ):
        all_blockers.append("fx_increase_monitor_or_return_risk")
    if target_pan is not None and abs(_safe_float(target_pan)) > 1.0:
        if analysis.phase_correlation < MIN_PHASE_CORRELATION_FOR_WIDTH:
            all_blockers.append("phase_correlation_blocks_width")
        if analysis.mono_sum_delta_db <= MAX_MONO_SUM_LOSS_DB:
            all_blockers.append("mono_sum_loss_blocks_width")
    if width_widening:
        if analysis.phase_correlation < MIN_PHASE_CORRELATION_FOR_WIDTH:
            all_blockers.append("phase_correlation_blocks_width")
        if analysis.mono_sum_delta_db <= MAX_MONO_SUM_LOSS_DB:
            all_blockers.append("mono_sum_loss_blocks_width")
    if parameters.get("wing_eq_value_mapping_supported") is False:
        all_blockers.append(WING_EQ_VALUE_MAPPING_BLOCKER)
    if parameters.get("wing_dynamic_eq_value_mapping_supported") is False:
        all_blockers.append(WING_DYNAMIC_EQ_VALUE_MAPPING_BLOCKER)
    if parameters.get("wing_fx_model_parameter_operator_owned_model_blocks_apply") is True:
        all_blockers.append(WING_FX_OPERATOR_OWNED_MODEL_BLOCKER)
    elif (
        parameters.get("wing_fx_model_parameter_binding_required") is True
        and parameters.get("wing_fx_model_parameter_path_pattern_apply_ready") is not True
    ):
        all_blockers.append(WING_FX_MODEL_PARAMETER_BLOCKER)
    if parameters.get("wing_fx_send_source_binding_required") is True:
        all_blockers.append(WING_FX_SEND_SOURCE_SURFACE_BLOCKER)
    if parameters.get("wing_compressor_detector_parse_blocker"):
        all_blockers.append(WING_COMPRESSOR_DETECTOR_BLOCKER)
    if mode == "live" and aggressive:
        all_blockers.append("aggressive_live_strategy_requires_operator_review")
    if (
        mode == "live"
        and method_family == "dynamics"
        and makeup_gain_db > 0.0
    ):
        all_blockers.append(
            "live_dynamics_makeup_gain_requires_operator_review_and_wing_proof"
        )
    if (
        mode == "live"
        and method_family == "dynamics"
        and _safe_float(parameters.get("target_gain_reduction_db"), 0.0)
        > LIVE_DYNAMICS_MAX_TARGET_GAIN_REDUCTION_DB
    ):
        all_blockers.append("live_dynamics_target_gr_exceeds_conservative_limit")
    if mode == "soundcheck" and method_family == "dynamics":
        target_gr = _safe_float(parameters.get("target_gain_reduction_db"), 0.0)
        if target_gr > SOUNDCHECK_DYNAMICS_MAX_TARGET_GAIN_REDUCTION_DB:
            all_blockers.append("soundcheck_dynamics_target_gr_exceeds_bounded_limit")
        if makeup_gain_db > SOUNDCHECK_DYNAMICS_MAX_MAKEUP_GAIN_DB:
            all_blockers.append("soundcheck_dynamics_makeup_gain_exceeds_bounded_limit")
    if (
        mode == "live"
        and method_family == "de_esser"
        and _safe_float(parameters.get("range_db"), 0.0)
        > LIVE_DE_ESSER_MAX_RANGE_DB
    ):
        all_blockers.append("live_de_esser_range_exceeds_conservative_limit")
    if mode == "live" and method_family == "eq":
        gain_db = _safe_float(parameters.get("gain_db"), 0.0)
        if gain_db > LIVE_EQ_MAX_BOOST_DB:
            all_blockers.append(
                "live_eq_boost_requires_operator_review_and_wing_proof"
            )
        if gain_db < -LIVE_EQ_MAX_CUT_DB:
            all_blockers.append("live_eq_cut_exceeds_conservative_limit")
    if mode == "soundcheck" and method_family == "eq":
        gain_db = _safe_float(parameters.get("gain_db"), 0.0)
        if gain_db > SOUNDCHECK_EQ_MAX_BOOST_DB:
            all_blockers.append("soundcheck_eq_boost_exceeds_bounded_limit")
    if mode == "soundcheck" and method_family == "pan":
        pan_delta_percent = _safe_float(parameters.get("pan_delta_percent"), 0.0)
        bounded_delta_percent = _safe_float(
            parameters.get("bounded_delta_percent"),
            abs(pan_delta_percent),
        )
        if target_pan is not None and abs(_safe_float(target_pan)) > SOUNDCHECK_PAN_MAX_DELTA_PERCENT:
            all_blockers.append("soundcheck_pan_target_exceeds_bounded_limit")
        if (
            abs(pan_delta_percent) > SOUNDCHECK_PAN_MAX_DELTA_PERCENT
            or abs(bounded_delta_percent) > SOUNDCHECK_PAN_MAX_DELTA_PERCENT
        ):
            all_blockers.append("soundcheck_pan_delta_exceeds_bounded_limit")
        if target_width is not None:
            target_width_percent = _safe_float(target_width)
            if target_width_percent < SOUNDCHECK_WIDTH_MIN_TARGET_PERCENT:
                all_blockers.append("soundcheck_width_negative_target_requires_operator_review")
            if (
                target_width_percent > 100.0 + SOUNDCHECK_WIDTH_MAX_WIDEN_PERCENT
                or width_delta > SOUNDCHECK_WIDTH_MAX_WIDEN_PERCENT
            ):
                all_blockers.append("soundcheck_width_widening_exceeds_bounded_limit")
            if width_delta < -SOUNDCHECK_WIDTH_MAX_REDUCTION_PERCENT:
                all_blockers.append("soundcheck_width_reduction_exceeds_bounded_limit")
    if mode == "soundcheck" and method_family in {"gate", "expander"}:
        range_db = _safe_float(parameters.get("range_db"), 0.0)
        hysteresis_review_db = _safe_float(
            parameters.get("post_gate_hysteresis_review_db"), 0.0
        )
        hit_bleed_margin = _safe_float(
            parameters.get("gate_hit_to_bleed_margin_db"), 0.0
        )
        if range_db > SOUNDCHECK_GATE_EXPANDER_MAX_RANGE_DB:
            all_blockers.append("soundcheck_gate_expander_range_exceeds_bounded_limit")
        if hysteresis_review_db > SOUNDCHECK_GATE_EXPANDER_MAX_HYSTERESIS_REVIEW_DB:
            all_blockers.append(
                "soundcheck_gate_expander_hysteresis_review_exceeds_bounded_limit"
            )
        if method_family == "gate" and (
            hit_bleed_margin < SOUNDCHECK_GATE_EXPANDER_MIN_HIT_BLEED_MARGIN_DB
        ):
            all_blockers.append("soundcheck_gate_clean_hit_bleed_evidence_required")
    if mode == "soundcheck" and method_family == "fx":
        send_delta_db = _safe_float(parameters.get("send_delta_db"), 0.0)
        return_delta_db = _safe_float(parameters.get("return_delta_db"), 0.0)
        if (
            send_delta_db > SOUNDCHECK_FX_MAX_BOOST_DB
            or return_delta_db > SOUNDCHECK_FX_MAX_BOOST_DB
        ):
            all_blockers.append("soundcheck_fx_boost_exceeds_bounded_limit")
        if (
            send_delta_db < -SOUNDCHECK_FX_MAX_PULLBACK_DB
            or return_delta_db < -SOUNDCHECK_FX_MAX_PULLBACK_DB
        ):
            all_blockers.append("soundcheck_fx_pullback_exceeds_bounded_limit")
    master_output_delta_db = _soundcheck_master_output_delta_db(parameters)
    if (
        mode == "soundcheck"
        and _soundcheck_master_output_targets_main(parameters, analysis)
        and master_output_delta_db is not None
    ):
        if master_output_delta_db > SOUNDCHECK_MASTER_MAX_LIFT_DB:
            all_blockers.append("soundcheck_master_output_lift_exceeds_bounded_limit")
        if master_output_delta_db < -SOUNDCHECK_MASTER_MAX_PULLBACK_DB:
            all_blockers.append(
                "soundcheck_master_output_pullback_exceeds_bounded_limit"
            )
        if master_output_delta_db > 0.0:
            required_headroom = (
                master_output_delta_db + SOUNDCHECK_MASTER_MIN_HEADROOM_MARGIN_DB
            )
            if analysis.true_peak_headroom_db < required_headroom:
                all_blockers.append(
                    "soundcheck_master_output_lift_requires_true_peak_headroom"
                )
            if (
                analysis.summed_bus_evidence_available
                and analysis.summed_bus_true_peak_headroom_db < required_headroom
            ):
                all_blockers.append(
                    "soundcheck_master_output_lift_requires_summed_bus_headroom"
                )
    master_processing_types = _soundcheck_master_processing_types(parameters)
    if (
        mode == "soundcheck"
        and _wing_target_base_template(analysis.target_id)[1] == "main"
        and master_processing_types
    ):
        if "broad_eq" in master_processing_types:
            master_eq_gain = _safe_float(parameters.get("gain_db"), 0.0)
            if master_eq_gain > SOUNDCHECK_MASTER_EQ_MAX_BOOST_DB:
                all_blockers.append(
                    "soundcheck_master_processing_eq_boost_requires_operator_review"
                )
            if master_eq_gain < -SOUNDCHECK_MASTER_EQ_MAX_CUT_DB:
                all_blockers.append(
                    "soundcheck_master_processing_eq_cut_exceeds_bounded_limit"
                )
        if (
            "bus_compression" in master_processing_types
            and _safe_float(parameters.get("target_gain_reduction_db"), 0.0)
            > SOUNDCHECK_MASTER_BUS_COMPRESSION_MAX_TARGET_GR_DB
        ):
            all_blockers.append(
                "soundcheck_master_processing_bus_compression_gr_exceeds_bounded_limit"
            )
        if (
            "limiter" in master_processing_types
            and _safe_float(parameters.get("target_gain_reduction_db"), 0.0)
            > SOUNDCHECK_MASTER_LIMITER_MAX_TARGET_GR_DB
        ):
            all_blockers.append(
                "soundcheck_master_processing_limiter_gr_exceeds_bounded_limit"
            )
        if makeup_gain_db > 0.0:
            all_blockers.append(
                "soundcheck_master_processing_makeup_gain_requires_headroom_review"
            )
    if mode == "live" and method_family == "fx":
        send_delta_db = _safe_float(parameters.get("send_delta_db"), 0.0)
        return_delta_db = _safe_float(parameters.get("return_delta_db"), 0.0)
        if send_delta_db > LIVE_FX_MAX_BOOST_DB or return_delta_db > LIVE_FX_MAX_BOOST_DB:
            all_blockers.append(
                "live_fx_boost_requires_operator_review_and_wing_proof"
            )
        if (
            send_delta_db < -LIVE_FX_MAX_PULLBACK_DB
            or return_delta_db < -LIVE_FX_MAX_PULLBACK_DB
        ):
            all_blockers.append("live_fx_pullback_exceeds_conservative_limit")
        if set(parameters) & set(WING_FX_MODEL_SPECIFIC_PARAMETER_KEYS):
            all_blockers.append(
                "live_fx_model_or_time_edit_requires_operator_review_and_wing_proof"
            )
    parameters = _with_live_stepped_move_guard(
        parameters,
        analysis=analysis,
        method_family=method_family,
    )
    parameters = _with_live_dynamics_conservative_guard(
        parameters,
        analysis=analysis,
        method_family=method_family,
    )
    parameters = _with_soundcheck_dynamics_guard(
        parameters,
        analysis=analysis,
        method_family=method_family,
    )
    parameters = _with_live_de_esser_conservative_guard(
        parameters,
        analysis=analysis,
        method_family=method_family,
    )
    parameters = _with_live_eq_conservative_guard(
        parameters,
        analysis=analysis,
        method_family=method_family,
    )
    parameters = _with_live_fx_pullback_guard(
        parameters,
        analysis=analysis,
        method_family=method_family,
    )
    parameters = _with_soundcheck_fx_bounded_guard(
        parameters,
        analysis=analysis,
        method_family=method_family,
    )
    parameters = _with_live_master_true_peak_output_guard(
        parameters,
        analysis=analysis,
        method_family=method_family,
    )
    parameters = _with_soundcheck_master_output_guard(
        parameters,
        analysis=analysis,
        method_family=method_family,
    )
    parameters = _with_soundcheck_master_processing_guard(
        parameters,
        analysis=analysis,
        method_family=method_family,
    )
    parameters = _with_soundcheck_eq_boost_guard(
        parameters,
        analysis=analysis,
        method_family=method_family,
    )
    parameters = _with_soundcheck_pan_width_guard(
        parameters,
        analysis=analysis,
        method_family=method_family,
    )
    parameters = _with_live_pan_width_hold_guard(
        parameters,
        analysis=analysis,
        method_family=method_family,
        strategy_id=strategy_id,
    )
    parameters = _with_live_phase_mono_hold_guard(
        parameters,
        analysis=analysis,
        method_family=method_family,
        strategy_id=strategy_id,
    )
    parameters = _with_soundcheck_gate_expander_guard(
        parameters,
        analysis=analysis,
        method_family=method_family,
    )
    effective_target_id = _effective_wing_target_id(
        analysis.target_id,
        parameters,
        method_family=method_family,
    )
    if effective_target_id != analysis.target_id:
        parameters = dict(parameters)
        parameters.setdefault("wing_osc_original_target_id", analysis.target_id)
        parameters.setdefault("wing_osc_effective_target_id", effective_target_id)
    if not _wing_target_resolves_to_osc_surface(effective_target_id, method_family):
        all_blockers.append(WING_OSC_UNRESOLVED_TARGET_BLOCKER)
    parameters = _with_wing_native_parameter_mappings(
        parameters,
        target_id=effective_target_id,
        method_family=method_family,
    )

    blockers_tuple = _ordered_unique(all_blockers)
    normalized_scores = {
        "speed": round(_clip01(scores.get("speed")), 3),
        "precision": round(_clip01(scores.get("precision")), 3),
        "musical": round(_clip01(scores.get("musical")), 3),
        "safety": round(_clip01(scores.get("safety")), 3),
        "reversibility": round(_clip01(scores.get("reversibility")), 3),
        "operator_clarity": round(_clip01(scores.get("operator_clarity")), 3),
    }
    total = _candidate_score(normalized_scores, mode=mode, blockers=blockers_tuple)
    confidence = round(
        _clip(
            0.58 * total
            + 0.27 * _clip01(analysis.evidence_confidence)
            + 0.15 * _clip01(analysis.source_identity_confidence),
            0.0,
            1.0,
        ),
        3,
    )
    return DSPStrategyCandidate(
        strategy_id=strategy_id,
        method_family=method_family,
        problem=problem,
        parameters=parameters,
        scores=normalized_scores,
        total_score=total,
        confidence=confidence,
        reason=reason,
        operator_check=operator_check,
        rollback_expectation=_rollback_expectation(method_family),
        future_wing_readback_contract=_future_readback_contract(
            method_family,
            effective_target_id,
            parameters,
        ),
        blockers=blockers_tuple,
    )


def _with_live_stepped_move_guard(
    parameters: Dict[str, Any],
    *,
    analysis: SmartDSPAnalysisInput,
    method_family: str,
) -> Dict[str, Any]:
    if normalize_mode(analysis.mode) != "live":
        return parameters
    if method_family not in LIVE_STEPPED_MOVE_FAMILIES:
        return parameters
    updated = dict(parameters)
    db_delta_keys = (
        "delta_db",
        "bounded_delta_db",
        "bus_delta_db",
        "source_delta_db",
        "group_delta_db",
        "trim_delta_db",
        "send_delta_db",
        "return_delta_db",
    )
    pan_delta_keys = (
        "pan_delta_percent",
        "bounded_delta_percent",
        "width_delta_percent",
    )
    has_db_move = any(
        key in updated and abs(_safe_float(updated.get(key))) > 0.0
        for key in db_delta_keys
    )
    has_pan_move = any(
        key in updated and abs(_safe_float(updated.get(key))) > 0.0
        for key in pan_delta_keys
    )
    if not has_db_move and not has_pan_move:
        return updated
    updated.setdefault("live_no_sudden_jump_guard", True)
    updated.setdefault("live_stepped_change_required", True)
    updated.setdefault("live_readback_after_each_step_required", True)
    updated.setdefault("live_min_step_interval_ms", LIVE_MIN_STEP_INTERVAL_MS)
    updated.setdefault("live_rate_limit_reason", "avoid_abrupt_live_mix_jump")
    if has_db_move:
        updated.setdefault("live_max_single_step_db", LIVE_MAX_SINGLE_STEP_DB)
    if has_pan_move:
        updated.setdefault("live_max_single_step_percent", LIVE_MAX_SINGLE_STEP_PERCENT)
    return updated


def _with_live_dynamics_conservative_guard(
    parameters: Dict[str, Any],
    *,
    analysis: SmartDSPAnalysisInput,
    method_family: str,
) -> Dict[str, Any]:
    if normalize_mode(analysis.mode) != "live" or method_family != "dynamics":
        return parameters
    updated = dict(parameters)
    crossover_review_values = {
        key: updated.get(key)
        for key in (
            "compressor_crossover_type",
            "compressor_crossover_depth_db",
            "compressor_crossover_frequency_hz",
            "compressor_crossover_parameter_source",
        )
        if key in updated
    }
    sidechain_review_values = {
        key: updated.get(key)
        for key in (
            "compressor_sidechain_filter_type",
            "compressor_sidechain_frequency_hz",
            "compressor_sidechain_q",
            "compressor_sidechain_source",
            "compressor_sidechain_tap",
            "compressor_sidechain_parameter_source",
            "compressor_sidechain_evidence_frequency_hz",
            "compressor_sidechain_low_end_pressure_score",
            "compressor_sidechain_plosive_risk_score",
            "compressor_sidechain_low_mid_bloom_score",
        )
        if key in updated
    }
    crossover_write_allowed = (
        updated.get("live_dynamics_crossover_write_allowed") is True
    )
    sidechain_write_allowed = (
        updated.get("live_dynamics_sidechain_write_allowed") is True
    )
    if not crossover_write_allowed:
        for key in (
            "compressor_crossover_type",
            "compressor_crossover_depth_db",
            "compressor_crossover_frequency_hz",
        ):
            updated.pop(key, None)
        for key in list(updated):
            if str(key).startswith("wing_compressor_crossover_"):
                updated.pop(key, None)
        updated.setdefault("live_dynamics_crossover_write_forbidden", True)
        updated.setdefault(
            "live_dynamics_crossover_review_only_values",
            crossover_review_values,
        )
    if not sidechain_write_allowed:
        for key in (
            "compressor_sidechain_filter_type",
            "compressor_sidechain_frequency_hz",
            "compressor_sidechain_q",
            "compressor_sidechain_source",
            "compressor_sidechain_tap",
        ):
            updated.pop(key, None)
        for key in list(updated):
            if str(key).startswith("wing_compressor_sidechain_"):
                updated.pop(key, None)
        updated.setdefault("live_dynamics_sidechain_write_forbidden", True)
        updated.setdefault(
            "live_dynamics_sidechain_review_only_values",
            sidechain_review_values,
        )
    updated.setdefault("live_dynamics_conservative_proposal", True)
    updated.setdefault("live_dynamics_minimal_write_set_required", True)
    updated.setdefault("live_dynamics_stepwise_threshold_review_required", True)
    updated.setdefault(
        "live_dynamics_max_threshold_step_db",
        LIVE_DYNAMICS_MAX_THRESHOLD_STEP_DB,
    )
    updated.setdefault(
        "live_dynamics_max_target_gain_reduction_db",
        LIVE_DYNAMICS_MAX_TARGET_GAIN_REDUCTION_DB,
    )
    updated.setdefault("live_dynamics_no_makeup_gain_required", True)
    updated.setdefault("live_dynamics_makeup_gain_db_limit", 0.0)
    updated.setdefault("live_dynamics_makeup_gain_write_forbidden", True)
    updated.setdefault(
        "live_dynamics_makeup_gain_review_only_db",
        _safe_float(updated.get("makeup_gain_db"), 0.0),
    )
    updated.setdefault(
        "live_dynamics_gain_reduction_meter_readback_after_each_step_required",
        True,
    )
    updated.setdefault("live_dynamics_previous_comp_model_readback_required", True)
    updated.setdefault("live_dynamics_global_on_mix_write_forbidden", True)
    updated.setdefault("live_dynamics_on_mix_readback_required", True)
    updated.setdefault("live_dynamics_compressor_enable_write_forbidden", True)
    updated.setdefault("live_dynamics_compressor_mix_write_forbidden", True)
    updated.setdefault("live_dynamics_parameter_write_forbidden", True)
    updated.setdefault("live_dynamics_parameter_readback_required", True)
    updated.setdefault(
        "live_dynamics_parameter_apply_blocked_without_wing_proof",
        True,
    )
    updated.setdefault(
        "live_dynamics_parameter_review_only_reason",
        "live_dynamics_must_read_existing_compressor_state_and_operator_confirm_before_parameter_apply",
    )
    updated.setdefault(
        "live_dynamics_requires_existing_compressor_enabled_readback",
        True,
    )
    updated.setdefault(
        "live_dynamics_compressor_on_review_only_value",
        updated.get("wing_compressor_on_osc_value", WING_COMPRESSOR_ON_MAX),
    )
    updated.setdefault(
        "live_dynamics_compressor_mix_review_only_value",
        updated.get("wing_compressor_mix_osc_value"),
    )
    updated.setdefault(
        "live_dynamics_global_on_mix_review_only_reason",
        "live_dynamics_must_read_existing_compressor_on_and_mix_before_parameter_apply",
    )
    updated.setdefault("live_dynamics_operator_rehearsal_required", True)
    updated.setdefault(
        "live_dynamics_live_promotion_status",
        "blocked_until_real_wing_readback_operator_rehearsal_and_rollback",
    )
    updated.setdefault("live_dynamics_live_apply_blocked_without_wing_proof", True)
    return updated


def _with_soundcheck_dynamics_guard(
    parameters: Dict[str, Any],
    *,
    analysis: SmartDSPAnalysisInput,
    method_family: str,
) -> Dict[str, Any]:
    if normalize_mode(analysis.mode) != "soundcheck" or method_family != "dynamics":
        return parameters
    dynamics_keys = {
        "threshold_dbfs",
        "compressor_enabled",
        "ratio",
        "attack_ms",
        "hold_ms",
        "release_ms",
        "knee_db",
        "target_gain_reduction_db",
        "makeup_gain_db",
        "compression_mix_percent",
        "wing_compressor_threshold_osc_value",
        "wing_compressor_makeup_gain_osc_value",
    }
    if not (set(parameters) & dynamics_keys):
        return parameters
    updated = dict(parameters)
    makeup_gain = max(0.0, _safe_float(updated.get("makeup_gain_db"), 0.0))
    if makeup_gain > 0.0:
        required_min_headroom = round(
            makeup_gain + SOUNDCHECK_DYNAMICS_MIN_HEADROOM_MARGIN_DB,
            3,
        )
        required_headroom = _safe_float(
            updated.get("requires_true_peak_headroom_db"),
            required_min_headroom,
        )
        required_summed_headroom = _safe_float(
            updated.get("requires_summed_bus_true_peak_headroom_db"),
            required_headroom,
        )
        updated.setdefault("requires_true_peak_headroom_db", required_headroom)
        updated.setdefault(
            "requires_summed_bus_true_peak_headroom_db",
            required_summed_headroom,
        )
        updated.setdefault(
            "soundcheck_dynamics_required_true_peak_headroom_db",
            required_headroom,
        )
        updated.setdefault(
            "soundcheck_dynamics_required_summed_bus_true_peak_headroom_db",
            required_summed_headroom,
        )
    updated.setdefault("soundcheck_dynamics_bounded_compression_proposal", True)
    updated.setdefault("soundcheck_dynamics_native_compressor_osc_only_required", True)
    updated.setdefault(
        "soundcheck_dynamics_max_target_gain_reduction_db",
        SOUNDCHECK_DYNAMICS_MAX_TARGET_GAIN_REDUCTION_DB,
    )
    updated.setdefault(
        "soundcheck_dynamics_max_makeup_gain_db",
        SOUNDCHECK_DYNAMICS_MAX_MAKEUP_GAIN_DB,
    )
    updated.setdefault(
        "soundcheck_dynamics_min_headroom_margin_db",
        SOUNDCHECK_DYNAMICS_MIN_HEADROOM_MARGIN_DB,
    )
    updated.setdefault("soundcheck_dynamics_target_gr_review_only", True)
    updated.setdefault("soundcheck_dynamics_target_gr_readback_required", True)
    updated.setdefault("soundcheck_dynamics_makeup_gain_headroom_required", True)
