def _fx_level_write_key_sets(move_kinds: Sequence[str]) -> Tuple[List[str], List[str]]:
    move_kind_set = {str(move_kind) for move_kind in move_kinds}
    selected_write_keys = [
        WING_FX_LEVEL_WRITE_KEY_BY_MOVE_KIND[move_kind]
        for move_kind in ("send_level", "return_level")
        if move_kind in move_kind_set
    ]
    forbidden_write_keys = [
        key
        for key in WING_FX_LEVEL_WRITE_PARAMETER_KEYS
        if key not in selected_write_keys
    ]
    return selected_write_keys, forbidden_write_keys


def _with_live_fx_pullback_guard(
    parameters: Dict[str, Any],
    *,
    analysis: SmartDSPAnalysisInput,
    method_family: str,
) -> Dict[str, Any]:
    if normalize_mode(analysis.mode) != "live" or method_family != "fx":
        return parameters
    send_delta_db = _safe_float(parameters.get("send_delta_db"), 0.0)
    return_delta_db = _safe_float(parameters.get("return_delta_db"), 0.0)
    if send_delta_db == 0.0 and return_delta_db == 0.0:
        return parameters
    updated = dict(parameters)
    move_kinds: List[str] = []
    if any(
        abs(_safe_float(updated.get(key), 0.0)) > 0.0
        for key in ("send_delta_db", "wing_fx_send_level_delta_db")
    ):
        move_kinds.append("send_level")
    if any(
        abs(_safe_float(updated.get(key), 0.0)) > 0.0
        for key in ("return_delta_db", "wing_fx_return_delta_db")
    ):
        move_kinds.append("return_level")
    selected_write_keys, forbidden_write_keys = _fx_level_write_key_sets(move_kinds)
    updated.setdefault("live_fx_pullback_only_proposal", True)
    updated.setdefault("live_fx_level_reduction_only_required", True)
    updated.setdefault("live_fx_max_pullback_db", LIVE_FX_MAX_PULLBACK_DB)
    updated.setdefault("live_fx_max_boost_db", LIVE_FX_MAX_BOOST_DB)
    updated.setdefault("live_fx_native_level_osc_only_required", True)
    updated.setdefault("live_fx_no_model_or_time_parameter_write_required", True)
    updated.setdefault(
        "live_fx_model_time_edit_review_only_fields",
        list(WING_FX_POST_PULLBACK_MODEL_TIME_REVIEW_FIELDS),
    )
    updated.setdefault("live_fx_absolute_level_readback_required", True)
    updated.setdefault("live_fx_monitor_feedback_recheck_after_apply_required", True)
    updated.setdefault("live_fx_return_headroom_recheck_after_apply_required", True)
    updated.setdefault("live_fx_operator_rehearsal_required", True)
    updated.setdefault("live_fx_level_move_kinds", move_kinds)
    updated.setdefault("live_fx_apply_only_selected_write_keys", True)
    updated.setdefault("live_fx_selected_write_keys", selected_write_keys)
    updated.setdefault("live_fx_forbidden_write_keys", forbidden_write_keys)
    updated.setdefault(
        "live_fx_live_promotion_status",
        "blocked_until_real_wing_fx_level_readback_monitor_recheck_and_rollback",
    )
    updated.setdefault("live_fx_live_apply_blocked_without_wing_proof", True)
    return updated


def _with_soundcheck_fx_bounded_guard(
    parameters: Dict[str, Any],
    *,
    analysis: SmartDSPAnalysisInput,
    method_family: str,
) -> Dict[str, Any]:
    if normalize_mode(analysis.mode) != "soundcheck" or method_family != "fx":
        return parameters
    fx_level_keys = {
        "send_delta_db",
        "return_delta_db",
        "wing_fx_send_level_delta_db",
        "wing_fx_return_delta_db",
    }
    review_only_fields = list(WING_SOUNDCHECK_FX_MODEL_TIME_REVIEW_ONLY_FIELDS)
    if not (
        set(parameters) & fx_level_keys
        or set(parameters) & set(WING_FX_MODEL_SPECIFIC_PARAMETER_KEYS)
        or set(parameters) & set(review_only_fields)
    ):
        return parameters

    updated = dict(parameters)
    move_kinds: List[str] = []
    if any(
        abs(_safe_float(updated.get(key), 0.0)) > 0.0
        for key in ("send_delta_db", "wing_fx_send_level_delta_db")
    ):
        move_kinds.append("send_level")
    if any(
        abs(_safe_float(updated.get(key), 0.0)) > 0.0
        for key in ("return_delta_db", "wing_fx_return_delta_db")
    ):
        move_kinds.append("return_level")
    selected_write_keys, forbidden_write_keys = _fx_level_write_key_sets(move_kinds)
    has_model_time_review = bool(
        set(updated) & set(review_only_fields)
        or set(updated) & set(WING_FX_MODEL_SPECIFIC_PARAMETER_KEYS)
    )

    updated.setdefault("soundcheck_fx_bounded_level_proposal", True)
    updated.setdefault("soundcheck_fx_native_level_osc_only_required", True)
    updated.setdefault("soundcheck_fx_max_pullback_db", SOUNDCHECK_FX_MAX_PULLBACK_DB)
    updated.setdefault("soundcheck_fx_max_boost_db", SOUNDCHECK_FX_MAX_BOOST_DB)
    updated.setdefault("soundcheck_fx_level_move_kinds", move_kinds)
    updated.setdefault("soundcheck_fx_apply_only_selected_write_keys", True)
    updated.setdefault("soundcheck_fx_selected_write_keys", selected_write_keys)
    updated.setdefault("soundcheck_fx_forbidden_write_keys", forbidden_write_keys)
    updated.setdefault(
        "soundcheck_fx_no_model_or_time_parameter_write_required",
        True,
    )
    updated.setdefault(
        "soundcheck_fx_model_time_edit_review_only_fields",
        review_only_fields,
    )
    updated.setdefault(
        "soundcheck_fx_followup_model_time_review_required",
        has_model_time_review,
    )
    updated.setdefault("soundcheck_fx_absolute_level_readback_required", True)
    updated.setdefault(
        "soundcheck_fx_monitor_feedback_recheck_after_apply_required",
        True,
    )
    updated.setdefault(
        "soundcheck_fx_return_headroom_recheck_after_apply_required",
        True,
    )
    updated.setdefault("soundcheck_fx_operator_confirmation_required", True)
    updated.setdefault("soundcheck_fx_readback_required", True)
    updated.setdefault("soundcheck_fx_rollback_ready", True)
    updated.setdefault(
        "soundcheck_fx_live_promotion_status",
        "blocked_until_real_wing_fx_level_readback_monitor_return_headroom_recheck_and_operator_approval",
    )
    updated.setdefault("soundcheck_fx_live_apply_blocked_without_wing_proof", True)
    return updated


def _soundcheck_master_output_delta_db(
    parameters: Mapping[str, Any],
) -> Optional[float]:
    for key in ("wing_gain_delta_db", "trim_delta_db", "bounded_delta_db"):
        numeric = _numeric_float_or_none(parameters.get(key))
        if numeric is not None and abs(numeric) >= 1e-9:
            return numeric
    return None


def _soundcheck_master_output_targets_main(
    parameters: Mapping[str, Any],
    analysis: SmartDSPAnalysisInput,
) -> bool:
    _base, surface = _wing_target_base_template(analysis.target_id)
    if surface == "main":
        return True
    if str(parameters.get("target_scope") or "") == "master_and_pa_feed":
        return True
    master_output_markers = {
        "target_true_peak_dbtp",
        "target_master_integrated_lufs",
        "master_loudness_excess_lu",
        "master_loudness_deficit_lu",
        "master_true_peak_pullback_db",
        "headroom_deficit_pullback_db",
    }
    return (
        parameters.get("pa_reference_feed_check_required") is True
        and bool(master_output_markers & set(parameters))
    )


