def _forbidden_routing_scene_snapshot_tokens(
    analysis: SmartDSPAnalysisInput,
) -> Tuple[str, ...]:
    haystacks = [
        _normalize_intent_text(analysis.operator_intent),
        *(_normalize_intent_text(item) for item in analysis.problem_hints),
    ]
    matches: List[str] = []
    for haystack in haystacks:
        if not haystack:
            continue
        padded = f"_{haystack}_"
        for token in FORBIDDEN_ROUTING_SCENE_SNAPSHOT_TOKENS:
            normalized = _normalize_intent_text(token)
            if f"_{normalized}_" in padded:
                matches.append(normalized)
    return _ordered_unique(matches)


