def _global_blockers(
    analysis: SmartDSPAnalysisInput,
    mode: str,
    current_state_freshness: Mapping[str, Any],
) -> Tuple[str, ...]:
    blockers: List[str] = []
    if mode not in SUPPORTED_MODES:
        blockers.append("unsupported_smart_dsp_mode")
    if not analysis.source_identity_confirmed:
        blockers.append("source_identity_not_confirmed")
    if analysis.source_identity_confidence < MIN_SOURCE_IDENTITY_CONFIDENCE:
        blockers.append("source_identity_confidence_low")
    if _source_identity_mismatch_active(analysis):
        blockers.append("source_identity_evidence_conflict")
    if analysis.evidence_confidence < MIN_AUDIO_EVIDENCE_CONFIDENCE:
        blockers.append("audio_evidence_confidence_low")
    if _audio_evidence_is_stale(analysis, mode):
        blockers.append("audio_evidence_stale")
    if _forbidden_routing_scene_snapshot_tokens(analysis):
        blockers.append("forbidden_routing_scene_snapshot_intent")
    if (
        mode == "live"
        and classify_source_family(analysis.source_role) != "master"
        and _live_master_output_intent_tokens(analysis)
    ):
        blockers.append("live_master_output_intent_requires_review")
    if (
        mode == "live"
        and classify_source_family(analysis.source_role) != "master"
        and not _live_master_output_intent_tokens(analysis)
        and _live_eq_change_intent_tokens(analysis)
    ):
        blockers.append("live_eq_intent_requires_review")
    if (
        mode == "live"
        and classify_source_family(analysis.source_role) != "master"
        and not _live_master_output_intent_tokens(analysis)
        and not _live_eq_change_intent_tokens(analysis)
        and _live_source_gain_up_intent_tokens(analysis)
    ):
        blockers.append("live_source_gain_up_intent_requires_review")
    if (
        mode == "live"
        and classify_source_family(analysis.source_role) != "master"
        and not _live_master_output_intent_tokens(analysis)
        and not _live_source_gain_up_intent_tokens(analysis)
        and _live_processing_change_intent_tokens(analysis)
    ):
        blockers.append("live_processing_intent_requires_review")
    if (
        mode == "live"
        and classify_source_family(analysis.source_role) != "master"
        and not _live_master_output_intent_tokens(analysis)
        and not _live_source_gain_up_intent_tokens(analysis)
        and not _live_processing_change_intent_tokens(analysis)
        and "pan_width"
        not in {_normalize_token(item, "") for item in analysis.problem_hints if item}
        and _live_pan_width_intent_tokens(analysis)
    ):
        blockers.append("live_pan_width_intent_requires_review")
    freshness_status = str(current_state_freshness.get("status") or "unknown")
    if freshness_status != "fresh":
        blockers.append("smart_dsp_context_cache_not_fresh")
    if freshness_status == "fresh" and not _freshness_is_no_authority(current_state_freshness):
        blockers.append("smart_dsp_context_cache_live_authority_present")
    if not analysis.current_state_readback_available:
        blockers.append("current_state_readback_missing")
    if not analysis.rollback_plan_available:
        blockers.append("rollback_plan_missing")
    if analysis.true_peak_headroom_db < MIN_TRUE_PEAK_HEADROOM_DB:
        blockers.append("true_peak_headroom_low")
    if analysis.auto_apply_requested:
        blockers.append("auto_apply_not_supported")
    return _ordered_unique(blockers)


def _context_recheck_required(global_blockers: Sequence[str]) -> bool:
    context_blockers = {
        "smart_dsp_context_cache_not_fresh",
        "smart_dsp_context_cache_live_authority_present",
        "current_state_readback_missing",
        "rollback_plan_missing",
    }
    return bool(context_blockers & set(global_blockers))


def _unsupported_mode_recheck_required(global_blockers: Sequence[str]) -> bool:
    return "unsupported_smart_dsp_mode" in set(global_blockers)


def _forbidden_operation_review_required(global_blockers: Sequence[str]) -> bool:
    return "forbidden_routing_scene_snapshot_intent" in set(global_blockers)


def _live_master_output_intent_review_required(global_blockers: Sequence[str]) -> bool:
    return "live_master_output_intent_requires_review" in set(global_blockers)


def _live_eq_intent_review_required(global_blockers: Sequence[str]) -> bool:
    return "live_eq_intent_requires_review" in set(global_blockers)


def _live_source_gain_up_intent_review_required(global_blockers: Sequence[str]) -> bool:
    return "live_source_gain_up_intent_requires_review" in set(global_blockers)


def _live_processing_intent_review_required(global_blockers: Sequence[str]) -> bool:
    return "live_processing_intent_requires_review" in set(global_blockers)


def _live_pan_width_intent_review_required(global_blockers: Sequence[str]) -> bool:
    return "live_pan_width_intent_requires_review" in set(global_blockers)


def _source_identity_confirmation_required(global_blockers: Sequence[str]) -> bool:
    identity_blockers = {
        "source_identity_not_confirmed",
        "source_identity_confidence_low",
    }
    return bool(identity_blockers & set(global_blockers)) and (
        "source_identity_evidence_conflict" not in set(global_blockers)
    )


def _audio_evidence_recheck_required(global_blockers: Sequence[str]) -> bool:
    audio_blockers = {
        "audio_evidence_confidence_low",
        "audio_evidence_stale",
    }
    return bool(audio_blockers & set(global_blockers))


def _auto_apply_review_required(global_blockers: Sequence[str]) -> bool:
    return "auto_apply_not_supported" in set(global_blockers)


def _global_blockers_are_live_intent_only(global_blockers: Sequence[str]) -> bool:
    blocker_set = set(global_blockers)
    return bool(blocker_set) and blocker_set <= LIVE_INTENT_REVIEW_BLOCKERS


def _global_blockers_allow_true_peak_pullback(global_blockers: Sequence[str]) -> bool:
    blocker_set = set(global_blockers)
    allowed_blockers = {"true_peak_headroom_low"} | set(LIVE_INTENT_REVIEW_BLOCKERS)
    return "true_peak_headroom_low" in blocker_set and blocker_set <= allowed_blockers


def _global_blockers_allow_feedback_priority(global_blockers: Sequence[str]) -> bool:
    blocker_set = set(global_blockers)
    allowed_blockers = {"true_peak_headroom_low"} | set(LIVE_INTENT_REVIEW_BLOCKERS)
    return blocker_set <= allowed_blockers


def _global_blockers_allow_fx_return_headroom_pullback(
    global_blockers: Sequence[str],
) -> bool:
    blocker_set = set(global_blockers)
    return blocker_set == {"true_peak_headroom_low"}


